"use strict";
/* History upgrade: question objects with the reason we ask, LR sources, and new presentations. */
(function(){const UP={"chest":{"ask":[{"q":"How quickly did the pain reach its worst: in a second, over a few minutes, or over an hour?","why":"Pain that is maximal within seconds comes from a mechanical event, a tearing intima, a clot lodging in a pulmonary artery or a pleural bleb rupturing, whereas ischaemic pain builds over minutes as supply-demand mismatch deepens.","changes":"Instantaneous maximal pain moves dissection, PE and pneumothorax ahead of ACS and makes you look for pulse deficits, hypoxia and a quiet hemithorax before the troponin.","lr":1.6,"target":"Aortic dissection","src":"Klompas 2002, JAMA RCE"},{"q":"Where does the pain go: into one arm, both arms, the jaw, or through to the back?","why":"Cardiac afferents converge on the same spinal segments (C8 to T4) as the arm and jaw dermatomes, so radiation to both arms or the right arm is convergence-projection from the heart and is hard to mimic with chest wall disease.","changes":"Radiation to both arms or the right arm raises the pre-test probability of MI enough that a single normal troponin should not reassure you.","lr":4.1,"target":"Acute MI","src":"Swap & Nagurney 2005, JAMA"},{"q":"Does it come on when you walk or climb stairs and settle when you stop?","why":"Exertion raises myocardial oxygen demand and a fixed stenosis cannot match it, so reproducible exertional pain that stops at rest is the physiology of supply-demand angina.","changes":"Exertional pain with rest relief should be treated as angina until the ECG and troponin and, if stable, a functional or CT coronary test say otherwise.","lr":2.4,"target":"Acute MI","src":"Swap & Nagurney 2005, JAMA"},{"q":"Were you sweaty, sick or did you vomit with it?","why":"Ischaemic pain drives a sympathetic and vagal surge; diaphoresis and vomiting are autonomic signatures of visceral pain and rarely accompany chest wall pain.","changes":"Autonomic features push you towards serial ECGs and troponins rather than discharge on a single normal set.","lr":2.0,"target":"Acute MI","src":"Swap & Nagurney 2005, JAMA"},{"q":"Is it the same as a previous heart attack or worse than your usual angina?","why":"A patient with coronary disease has already calibrated the sensation; recurrence of a known pain pattern is the brain recognising the same afferent input.","changes":"Treat as ACS and compare today's ECG with the old one.","lr":1.8,"target":"Acute MI","src":"Swap & Nagurney 2005, JAMA"},{"q":"Is it sharp and does it catch when you breathe in?","why":"Pleuritic pain is parietal pleura stretched by respiration, somatic rather than visceral, which is the opposite of ischaemic pain.","changes":"Pleuritic pain lowers the odds of MI but raises PE, pneumothorax, pneumonia and pericarditis, so the work-up changes rather than stops.","lr":0.2,"target":"Acute MI","src":"Panju 1998, JAMA RCE"},{"q":"Does it change when you move, twist or lie in a particular position?","why":"Positional pain comes from structures that move with posture: chest wall, pericardium and oesophagus, not the myocardium.","changes":"Positional pain argues against ACS and should prompt a look for a pericardial rub and a lean-forward relief pattern.","lr":0.3,"target":"Acute MI","src":"Panju 1998, JAMA RCE"},{"q":"Can I press on your chest where it hurts and see if that brings it on?","why":"Reproducing the exact pain by palpation localises it to chest wall tissue, but a third of patients with MI have some tenderness, so it lowers rather than excludes.","changes":"Tenderness that reproduces the pain allows a musculoskeletal diagnosis only once the ECG and troponin are normal.","lr":0.3,"target":"Acute MI","src":"Panju 1998, JAMA RCE"},{"q":"Did it feel like tearing or ripping, and did it go through to your back?","why":"A dissecting intimal flap separates the aortic media and the pain tracks along the aorta as it propagates, giving the tearing quality and migration to the interscapular region.","changes":"Tearing pain demands bilateral blood pressures, pulse comparison and CT aortography before any anticoagulant or antiplatelet.","lr":10.8,"target":"Aortic dissection","src":"Klompas 2002, JAMA RCE"},{"q":"Do you have Marfan syndrome, a known aortic aneurysm, or badly controlled blood pressure?","why":"Medial degeneration and chronic shear stress are the substrate for dissection; connective tissue disease and hypertension are the two commonest.","changes":"Risk substrate plus acute pain lowers your threshold for CT aortography even with a normal chest film.","lr":null,"target":"Aortic dissection","src":"Klompas 2002, JAMA RCE (Marfan history LR 4.1)"},{"q":"Have you been immobile, had surgery, cancer, a clot before, or are you on the pill or HRT, and is one leg swollen?","why":"These are Virchow's triad in history form: stasis, endothelial injury and hypercoagulability, and a swollen leg is the clot's source.","changes":"Any of these moves PE up the list and determines whether a Wells score lets you use D-dimer or go straight to CTPA.","lr":null,"target":"PE","src":"Wells 2000, Thromb Haemost; Goodacre 2005, Ann Intern Med (malignancy LR 2.7, previous DVT 2.3)"},{"q":"Did you faint or nearly faint with the pain?","why":"Syncope with chest pain means cardiac output fell abruptly: tamponade, a massive PE, critical aortic stenosis or an arrhythmia, not a chest wall problem.","changes":"Syncope with chest pain means monitoring, an ECG now and an echo or CT before the patient leaves the department.","lr":null,"target":"Dissection, PE, arrhythmia","src":"Klompas 2002, JAMA RCE (syncope in 13% of dissections); ESC syncope guideline 2018"},{"q":"Do you smoke, have diabetes, high blood pressure, high cholesterol, cocaine use, or heart disease in your family before 55 or 65?","why":"Risk factors set the pre-test probability on which every LR acts; cocaine adds vasospasm and thrombosis in young people without atheroma.","changes":"High risk burden lowers your threshold for serial troponins and admission; cocaine changes the treatment (benzodiazepines, avoid pure beta-blockade).","lr":null,"target":"ACS","src":"Body 2010, Resuscitation (risk factors weak individually in ED); Swap & Nagurney 2005, JAMA"}],"lrSrc":{"Radiation to both arms or shoulders":"Swap & Nagurney 2005, JAMA (LR 4.1; Panju 1998 JAMA RCE gave 7.1)","Radiation to the right arm":"Swap & Nagurney 2005, JAMA (right arm or shoulder LR 4.7)","Similar to previous MI or worse than previous angina":"Swap & Nagurney 2005, JAMA","Exertional":"Swap & Nagurney 2005, JAMA","Sweating":"Swap & Nagurney 2005, JAMA; Panju 1998, JAMA RCE","Nausea or vomiting":"Swap & Nagurney 2005, JAMA; Panju 1998, JAMA RCE","Pleuritic":"Panju 1998, JAMA RCE; Swap & Nagurney 2005, JAMA","Positional":"Panju 1998, JAMA RCE; Swap & Nagurney 2005, JAMA","Reproduced by palpation":"Panju 1998, JAMA RCE; Swap & Nagurney 2005, JAMA","Sharp or stabbing":"Panju 1998, JAMA RCE","Tearing or ripping pain":"Klompas 2002, JAMA RCE","Sudden onset, maximal at once":"Klompas 2002, JAMA RCE","Pain worse lying flat, better sitting forward":"unsourced (no pooled LR; listed as a diagnostic criterion in the ESC pericarditis guideline 2015)"}},"dysp":{"ask":[{"q":"Did this start over minutes, hours, or weeks?","why":"Minutes means a mechanical or vascular event (PE, pneumothorax, anaphylaxis, flash oedema); hours means bronchospasm, pneumonia or pulmonary oedema; weeks means effusion, anaemia or fibrosis, because each process fills the lung or blocks the circulation at a different rate.","changes":"Minute-scale onset means a chest X-ray and ECG now and a PE score before anything else.","lr":null,"target":"Timing of cause","src":"McGee, Evidence-Based Physical Diagnosis, 5th ed"},{"q":"How far can you walk on the flat before you must stop, and how many stairs?","why":"Exercise tolerance in metres or stairs converts a symptom into a measurable reserve; a patient who can climb two flights is not in acute decompensation whatever they say.","changes":"A fall from the usual baseline is what defines an exacerbation and justifies admission; the absence of exertional dyspnoea makes heart failure unlikely.","lr":0.5,"target":"HF","src":"Wang 2005, JAMA RCE (no dyspnoea on exertion LR 0.48)"},{"q":"How many pillows do you sleep on, and do you wake at night fighting for breath?","why":"Lying flat returns pooled venous blood to a failing left ventricle, raising pulmonary venous pressure; orthopnoea is immediate, paroxysmal nocturnal dyspnoea follows slower interstitial fluid reabsorption after one to two hours of sleep.","changes":"Orthopnoea or PND moves heart failure to the top and means a BNP, ECG and echo rather than an inhaler.","lr":2.6,"target":"HF","src":"Wang 2005, JAMA RCE (PND 2.6, orthopnoea 2.2)"},{"q":"Have you had heart failure or a heart attack before?","why":"Previous myocardial loss is the commonest substrate for pump failure; a known history is the single strongest historical item for heart failure as the cause.","changes":"Prior HF or MI makes decompensated heart failure the working diagnosis until the chest film and BNP say otherwise.","lr":5.8,"target":"HF","src":"Wang 2005, JAMA RCE (history of HF 5.8, history of MI 3.1)"},{"q":"Are both legs swollen, or just one?","why":"Bilateral oedema is raised right-sided filling pressure or low albumin; a single swollen leg is venous obstruction, which is the source of most pulmonary emboli.","changes":"One swollen leg with breathlessness means a Wells score and either D-dimer or CTPA that day.","lr":null,"target":"DVT or HF","src":"Goodacre 2005, Ann Intern Med (calf diameter difference LR 1.8 for DVT); Wang 2005, JAMA RCE (oedema on exam LR 2.3 for HF)"},{"q":"Do you wheeze, and does it vary through the day or with triggers?","why":"Wheeze is turbulent flow through narrowed intrathoracic airways; variability and triggers mark reversible bronchospasm rather than fixed obstruction.","changes":"Variable wheeze means peak flow or spirometry with reversibility and a trial of bronchodilator, not a diuretic.","lr":null,"target":"Asthma or COPD","src":"Straus 2000, JAMA RCE (wheeze on exam LR 3.8 for obstructive airway disease)"},{"q":"How many years have you smoked and how many a day?","why":"Cumulative smoke exposure destroys alveolar walls and inflames small airways; over 40 pack-years the odds of airflow obstruction rise about eightfold.","changes":"A heavy pack-year history with chronic dyspnoea means spirometry and a CXR for cancer rather than reassurance.","lr":8.3,"target":"COPD","src":"Straus 2000, JAMA RCE"},{"q":"Do you cough, bring anything up, and have you coughed blood?","why":"Purulent sputum points to airway infection; haemoptysis means a bleeding bronchial or alveolar source: cancer, bronchiectasis, PE infarct or TB.","changes":"Haemoptysis in a smoker over 40 needs a chest X-ray and, if normal, still referral for bronchoscopy or CT.","lr":null,"target":"Infection, cancer, PE","src":"Hamilton 2005, Thorax (haemoptysis PPV for lung cancer 2.4%)"},{"q":"Have you had chest pain with it, and is it sharp on breathing in?","why":"Pleuritic pain with sudden dyspnoea is pleural irritation from an infarct, pneumothorax or pneumonia; dull central pain with dyspnoea is ischaemia.","changes":"Pleuritic pain with dyspnoea and PE risk factors bypasses D-dimer if the Wells score is high.","lr":null,"target":"PE","src":"Wells 2000, Thromb Haemost; West 2007, QJM"},{"q":"Have you had fever or felt shivery?","why":"Fever with breathlessness means consolidation or sepsis-driven tachypnoea rather than a pure cardiac or airway cause.","changes":"Fever makes a chest film and CRP compulsory and triggers a CURB-65 if pneumonia is confirmed.","lr":null,"target":"Pneumonia","src":"Metlay 1997, JAMA RCE (subjective fever LR 1.7 to 2.1)"},{"q":"What do you do for work, and are your chest symptoms better on days off or holidays?","why":"Occupational asthma shows a work-related pattern because sensitiser exposure stops when the patient leaves; improvement away from work is sensitive but not specific.","changes":"A work-related pattern means serial peak flows at and away from work and referral before the patient loses the job or the lung.","lr":null,"target":"Occupational asthma","src":"Malo 1991, Am Rev Respir Dis (improvement on holiday sensitivity 88%, specificity about 24%)"},{"q":"Do you feel tingling in your fingers or around your mouth, or a sense of not getting enough air even at rest?","why":"Hyperventilation lowers PaCO2, causing alkalosis, ionised hypocalcaemia and paraesthesia; air hunger at rest with normal saturations and a clear chest fits anxiety only after organic causes are excluded.","changes":"Diagnose anxiety last, after oximetry, ECG, chest film and where indicated a D-dimer are normal.","lr":null,"target":"Anxiety or hyperventilation","src":"unsourced (diagnosis of exclusion; no pooled LR)"}],"lrSrc":{"History of heart failure":"Wang 2005, JAMA RCE","Paroxysmal nocturnal dyspnoea":"Wang 2005, JAMA RCE","Orthopnoea":"Wang 2005, JAMA RCE","History of MI":"Wang 2005, JAMA RCE","No dyspnoea on exertion":"Wang 2005, JAMA RCE (LR 0.48)","Smoking > 40 pack-years":"Straus 2000, JAMA RCE","Age > 45 with smoking and wheeze":"Straus 2000, JAMA RCE (all three present LR 156; none LR 0.02)","Sudden onset with pleuritic pain and risk factors":"unsourced as a single item (Wells 2000, Thromb Haemost, scores risk factors; no pooled LR for this combination)","Symptoms better on days off work":"Malo 1991, Am Rev Respir Dis (sensitivity 88%, specificity about 24%; no LR reported)"}},"head":{"ask":[{"q":"How long did it take to reach its worst: a second, a minute, or longer?","why":"Arterial blood entering the subarachnoid space raises intracranial pressure and irritates the meninges instantly, so SAH pain peaks within a minute; migraine and tension headache build over tens of minutes.","changes":"Peak within one minute means CT within six hours of onset and lumbar puncture if the CT is normal or late.","lr":null,"target":"SAH","src":"Perry 2013, JAMA (Ottawa SAH rule: thunderclap is a rule criterion); Perry 2011, BMJ (CT within 6 h sensitivity 100%)"},{"q":"Is this the first or worst headache of your life, or different from your usual ones?","why":"A primary headache patient has a template; a new pattern means a new process, and the brain reports deviation from the template more reliably than absolute severity.","changes":"A first or worst headache earns imaging; a familiar pattern with a normal examination does not.","lr":null,"target":"Secondary headache","src":"Detsky 2006, JAMA RCE"},{"q":"Is it worse lying down, coughing, straining or bending, and does it wake you?","why":"Raised intracranial pressure headache worsens when venous return falls and CSF pressure rises (lying, Valsalva, early morning); low-pressure headache does the reverse.","changes":"Valsalva or exertional worsening is a red flag for a mass or venous thrombosis and means imaging.","lr":null,"target":"Secondary headache","src":"Detsky 2006, JAMA RCE (aggravated by exertion or Valsalva LR 2.3)"},{"q":"Is it worse standing and better lying flat?","why":"Orthostatic headache means low CSF volume: a post-LP or spontaneous dural leak lets the brain sag and stretch pain-sensitive dura when upright.","changes":"Orthostatic headache after a procedure means an epidural blood patch discussion rather than analgesia alone.","lr":null,"target":"Low-pressure headache","src":"ICHD-3 2018 (diagnostic criterion)"},{"q":"If you are over 50: does your jaw ache when you chew, is your scalp tender, and has your vision changed?","why":"Giant cell arteritis narrows the external carotid branches so the masseter becomes ischaemic with use (claudication) and the superficial temporal artery is tender; the ophthalmic artery goes next.","changes":"Jaw claudication means ESR, CRP, high-dose steroid today and urgent temporal artery ultrasound or biopsy, not a wait for results.","lr":4.2,"target":"Giant cell arteritis","src":"Smetana & Shmerling 2002, JAMA RCE"},{"q":"Do you have fever, neck stiffness or a rash?","why":"Meningeal inflammation makes neck flexion painful and fever marks infection; a non-blanching rash is intravascular meningococcal multiplication.","changes":"Fever with headache and neck stiffness means blood cultures and antibiotics before the CT or LP.","lr":null,"target":"Meningitis","src":"Attia 1999, JAMA RCE (absence of all three of fever, neck stiffness, altered mental state virtually excludes meningitis)"},{"q":"Are you pregnant or recently delivered, do you have cancer or HIV, or take blood thinners?","why":"Each creates a specific secondary cause: pre-eclampsia and venous sinus thrombosis in pregnancy, metastases, opportunistic infection, and intracranial bleeding on anticoagulants.","changes":"Any of these turns a headache into an imaging decision and in pregnancy a blood pressure and urine dip.","lr":null,"target":"Secondary headache","src":"Do 2019, Neurology (SNNOOP10 red flags)"},{"q":"How many days a month do you take painkillers for headache?","why":"Regular analgesic use (over 10 to 15 days a month) sensitises central pain pathways so the headache perpetuates itself; the drug is the cause.","changes":"Medication overuse means withdrawal and a preventive, not another analgesic.","lr":null,"target":"Medication overuse headache","src":"ICHD-3 2018"},{"q":"Is it on one side, throbbing, and do you feel sick, avoid light, and have to stop what you are doing?","why":"These are the POUND features of migraine; trigeminovascular activation produces pulsating unilateral pain with nausea and photophobia and the brain cannot do much else.","changes":"Three POUND features make migraine likely; four or five make it very likely and imaging unnecessary with a normal examination.","lr":3.5,"target":"Migraine","src":"Detsky 2006, JAMA RCE (POUND 3 features LR 3.5; 4 to 5 features LR 24)"},{"q":"Before the headache, did you get flashing lights or tingling that spread over several minutes?","why":"Migraine aura is cortical spreading depression travelling at about 3 mm per minute, which gives the march; a TIA is maximal at once.","changes":"A marching aura supports migraine; a sudden fixed deficit does not and is treated as stroke.","lr":null,"target":"Migraine with aura","src":"ICHD-3 2018"},{"q":"Has anything changed in how you think, walk or see, or has anyone noticed you being different?","why":"A focal or cognitive deficit means the process has reached brain parenchyma, which no primary headache does.","changes":"Any neurological abnormality on history or examination means imaging regardless of the headache phenotype.","lr":5.3,"target":"Serious intracranial cause","src":"Detsky 2006, JAMA RCE"},{"q":"Does anyone else at home have headaches, and do you have a gas boiler or heater?","why":"Carbon monoxide binds haemoglobin and causes headache in everyone exposed; clustering in a household is the clue.","changes":"Household clustering means a carboxyhaemoglobin level and telling them to leave the house until it is checked.","lr":null,"target":"Carbon monoxide poisoning","src":"NICE CKS Headache 2024; Hampson 2012, Am J Respir Crit Care Med"}],"lrSrc":{"Thunderclap onset (peak within 1 minute)":"unsourced as an LR (it is a criterion of the Ottawa SAH rule, Perry 2013 JAMA, sensitivity 100%)","Age > 50 with new headache and jaw claudication":"Smetana & Shmerling 2002, JAMA RCE (jaw claudication LR 4.2)","Worse with Valsalva or exertion":"Detsky 2006, JAMA RCE (LR 2.3)","Abnormal neurological examination":"Detsky 2006, JAMA RCE","Nausea, photophobia, unilateral, disabling (POUND ≥ 3)":"Detsky 2006, JAMA RCE"}},"abdo":{"ask":[{"q":"Where did the pain start, and where is it now?","why":"Visceral pain from a distended appendix is felt in the periumbilical T10 dermatome; once inflammation reaches the parietal peritoneum the somatic nerves localise it to the right iliac fossa, so migration is the pathology moving outward.","changes":"Migration makes appendicitis likely enough to go to surgical review or imaging rather than observation.","lr":3.2,"target":"Appendicitis","src":"Wagner 1996, JAMA RCE (LR 3.18)"},{"q":"Which came first, the pain or the vomiting?","why":"In appendicitis the obstructed, distending appendix hurts first and reflex vomiting follows; in gastroenteritis the gut irritation produces vomiting first and crampy pain after.","changes":"Vomiting before pain pushes you towards gastroenteritis or obstruction and away from appendicitis.","lr":2.8,"target":"Appendicitis","src":"Wagner 1996, JAMA RCE (pain before vomiting LR 2.76)"},{"q":"Have you lost your appetite?","why":"Visceral inflammation suppresses appetite through vagal afferents; it is sensitive but common to many causes, so it helps little on its own.","changes":"Anorexia adds a point to an Alvarado score but should not change management alone.","lr":1.3,"target":"Appendicitis","src":"Wagner 1996, JAMA RCE (LR 1.27)"},{"q":"Is the pain constant or does it come in waves, and when did you last pass wind or open your bowels?","why":"Colicky pain is peristalsis against an obstruction; absent flatus means complete obstruction, and constant pain in a previously colicky patient means strangulation or ischaemia.","changes":"Colic with vomiting and no flatus means an abdominal film or CT, nasogastric tube and fluids.","lr":null,"target":"Bowel obstruction","src":"Böhner 1998, Eur J Surg (distension, vomiting, constipation and previous surgery as predictors; no pooled LR)"},{"q":"Where does the pain go: to the back, the shoulder tip, or the groin?","why":"Retroperitoneal organs (pancreas, aorta, posterior ulcer) refer to the back; diaphragmatic irritation refers to C4 at the shoulder; the ureter refers to the groin along T11 to L1.","changes":"Radiation decides whether lipase, aortic imaging or a urine dip comes first.","lr":null,"target":"Pancreatitis, AAA, renal colic","src":"McGee, Evidence-Based Physical Diagnosis, 5th ed"},{"q":"Does eating make it better or worse, and does it wake you at night?","why":"Duodenal ulcer pain eases with food that buffers acid and recurs at night; biliary and pancreatic pain follow fatty meals through CCK-driven contraction; mesenteric angina is post-prandial.","changes":"Post-prandial pain with weight loss in an arteriopath means CT angiography, not an endoscopy.","lr":null,"target":"Peptic, biliary, mesenteric","src":"McGee, Evidence-Based Physical Diagnosis, 5th ed"},{"q":"When was your last period, could you be pregnant, and is there any bleeding or discharge?","why":"A missed period with pain and bleeding is ectopic pregnancy until a scan shows an intrauterine pregnancy; the history alone cannot exclude it.","changes":"Every woman of reproductive age with abdominal pain gets a pregnancy test before any other decision.","lr":null,"target":"Ectopic pregnancy","src":"Crochet 2013, JAMA RCE (symptom LRs all below 1.5; bedside ultrasound LR 111)"},{"q":"Do you have atrial fibrillation, and is the pain far worse than you look?","why":"AF throws emboli into the superior mesenteric artery; the bowel wall has no somatic innervation until it infarcts, so early pain is severe but the abdomen is soft.","changes":"AF with severe pain and a soft abdomen means a lactate and CT angiography straight away.","lr":null,"target":"Mesenteric ischaemia","src":"Cudnik 2013, Acad Emerg Med (meta-analysis; no single history item with a reliable LR)"},{"q":"Did it start suddenly, are you over 60, do you smoke, and have you been told of an aneurysm?","why":"A rupturing aneurysm gives sudden pain, often to the back or flank, in exactly this demographic; the classic triad of pain, hypotension and pulsatile mass is present in a minority.","changes":"This combination means a bedside aortic ultrasound before the patient goes to CT.","lr":null,"target":"Ruptured AAA","src":"Lederle & Simel 1999, JAMA RCE (palpation only; no history LR)"},{"q":"Have you had abdominal surgery, a hernia, or do you take NSAIDs, steroids, blood thinners or drink heavily?","why":"Adhesions and hernias are the commonest causes of obstruction; NSAIDs and steroids cause and mask perforation; anticoagulants cause rectus sheath and retroperitoneal bleeds; alcohol causes pancreatitis.","changes":"Each item adds a specific diagnosis and a specific test (groin examination, erect chest film, haemoglobin, lipase).","lr":null,"target":"Obstruction, perforation, pancreatitis","src":"Böhner 1998, Eur J Surg; NICE NG104 pancreatitis 2018"},{"q":"Have you lost weight, bled from the bowel, changed bowel habit or gone yellow?","why":"These are the features of a tumour or biliary obstruction developing over weeks; they separate a chronic process from an acute one.","changes":"Over 50 with any of these means a two-week-wait referral even if the acute pain settles.","lr":null,"target":"Colorectal or pancreatic cancer","src":"NICE NG12 suspected cancer 2015"},{"q":"Do you have burning on passing urine, going more often, or blood in the urine, and any fever or rigors?","why":"Urinary symptoms with flank pain and rigors mean an obstructed or infected kidney; renal colic alone has no fever.","changes":"Fever with colic means an infected obstructed system and urgent imaging and decompression.","lr":null,"target":"Pyelonephritis, obstructed infected kidney","src":"NICE NG118 renal and ureteric stones 2019"}],"lrSrc":{"Pain migrating from periumbilical to RLQ":"Wagner 1996, JAMA RCE","Pain before vomiting":"Wagner 1996, JAMA RCE","Anorexia":"Wagner 1996, JAMA RCE","Vomiting before pain":"unsourced as 0.4 (Wagner 1996 reports pain-before-vomiting LR 2.76; the reciprocal negative LR for vomiting first is quoted in secondary summaries without a pooled value)","Colicky pain with vomiting and no flatus":"unsourced (Böhner 1998, Eur J Surg, identifies these as predictors without a pooled LR)","Pain out of proportion to signs in AF":"unsourced (Cudnik 2013, Acad Emerg Med, finds no reliable history LR)","Sudden severe pain in a patient with AAA risk":"unsourced (Lederle & Simel 1999, JAMA RCE, covers palpation only)","Missed period with pain and bleeding":"unsourced (Crochet 2013, JAMA RCE: symptom LRs all below 1.5)"}},"back":{"ask":[{"q":"Is the pain worse with movement and better with rest, or worse in the morning and better once you get going?","why":"Mechanical pain loads a structure and settles when unloaded; inflammatory pain comes from cytokine-driven enthesitis that stiffens overnight and eases with movement.","changes":"An inflammatory pattern under 40 means HLA-B27, CRP and a rheumatology referral rather than physiotherapy alone.","lr":3.1,"target":"Axial spondyloarthritis","src":"Rudwaleit 2006, Arthritis Rheum (2 of 4 inflammatory criteria LR 3.7; 3 of 4 LR 12.4)"},{"q":"Does the pain go below the knee, and is it one leg or both?","why":"Pain below the knee follows a dermatome and means a nerve root is compressed; bilateral leg pain means the compression is central, at the cauda equina.","changes":"Radicular pain is still treated conservatively; bilateral sciatica is an emergency MRI.","lr":null,"target":"Radiculopathy or cauda equina","src":"Deyo 1992, JAMA RCE (sciatica sensitivity 95% for disc herniation)"},{"q":"Any numbness between your legs, difficulty starting or feeling the flow of urine, or loss of bowel control?","why":"The sacral roots that carry saddle sensation and bladder control run in the centre of the cauda equina and are compressed first by a central disc; retention is the earliest objective sign.","changes":"Any of these means bladder scan, rectal examination and emergency MRI the same day.","lr":18,"target":"Cauda equina","src":"Deyo 1992, JAMA RCE (urinary retention sensitivity 90%, specificity 95%)"},{"q":"Have you ever had cancer?","why":"Breast, prostate, lung, kidney and thyroid tumours seed the vertebral venous plexus; a cancer history is the single most powerful historical predictor of spinal metastasis.","changes":"Cancer history with new back pain means ESR, imaging and no watchful waiting.","lr":14.7,"target":"Spinal malignancy","src":"Deyo & Diehl 1988, J Gen Intern Med"},{"q":"Have you lost weight without trying?","why":"Unintended weight loss marks a catabolic systemic process, usually tumour or chronic infection, not a disc.","changes":"Weight loss with back pain over 50 means bloods and imaging rather than a six-week trial of analgesia.","lr":2.7,"target":"Spinal malignancy","src":"Deyo & Diehl 1988, J Gen Intern Med"},{"q":"How old are you, and has this improved at all after a month?","why":"Mechanical back pain improves in most within four to six weeks; failure to improve past a month and age over 50 each raise the chance of a structural or malignant cause.","changes":"No improvement after a month in someone over 50 is the point at which imaging and inflammatory markers are justified.","lr":3.0,"target":"Spinal malignancy","src":"Deyo & Diehl 1988, J Gen Intern Med (failure to improve LR 3.0; age over 50 LR 2.7)"},{"q":"Have you had fever, do you inject drugs, or are you on steroids or immunosuppressed?","why":"Haematogenous seeding of the disc space needs bacteraemia or weak defences; injecting, lines and immunosuppression are how Staphylococcus reaches the spine.","changes":"Fever with back pain in these groups means blood cultures, CRP and MRI for discitis or epidural abscess.","lr":null,"target":"Spinal infection","src":"Deyo 1992, JAMA RCE (fever sensitivity 27 to 83% for spinal infection; no pooled LR)"},{"q":"Did it start with a fall or lifting, and do you have osteoporosis or take steroids?","why":"A weakened vertebral body fractures under loads a healthy one tolerates; steroids and osteoporosis lower the threshold to trivial trauma.","changes":"Trauma on a fragile skeleton means an X-ray before mobilisation and a bone health plan.","lr":null,"target":"Vertebral fracture","src":"Henschke 2013, Cochrane (prolonged corticosteroid use LR 12 to 48 across studies)"},{"q":"Is the pain worse at night or when you lie down?","why":"Tumour and infection do not unload with rest; mechanical pain usually does.","changes":"Night pain is a red flag that lowers the threshold for imaging.","lr":null,"target":"Malignancy or infection","src":"Deyo 1992, JAMA RCE"},{"q":"Does your leg pain come on with walking and ease when you sit or lean forward?","why":"Spinal stenosis narrows the canal further in extension; flexion opens it, which is why patients lean on a trolley and are fine cycling.","changes":"Neurogenic claudication means an MRI and, if disabling, a surgical opinion, and a check of foot pulses to exclude vascular claudication.","lr":null,"target":"Spinal stenosis","src":"Suri 2010, JAMA RCE (no pain when seated LR 7.4; improvement with sitting or leaning forward)"},{"q":"What does your job involve: lifting, driving, vibration, long standing, and how do you feel about the work?","why":"Load, posture and whole-body vibration provoke mechanical back pain; low job satisfaction predicts chronicity more strongly than the physical findings do.","changes":"A work pattern means adjusted duties and a fit note, not simple absence; low satisfaction means early psychosocial intervention.","lr":null,"target":"Chronicity risk","src":"Waddell 1998, The Back Pain Revolution; NICE NG59 2016"},{"q":"Do you think moving will damage your back, and how is your mood?","why":"Fear-avoidance beliefs and depression are yellow flags that predict transition to chronic pain and disability through deconditioning and central sensitisation.","changes":"Yellow flags mean reassurance, graded activity and a STarT Back stratified approach rather than rest and imaging.","lr":null,"target":"Chronic disability","src":"Hill 2011, Lancet (STarT Back); NICE NG59 2016"}],"lrSrc":{"History of cancer":"Deyo & Diehl 1988, J Gen Intern Med; Henschke 2013, Cochrane","Unexplained weight loss":"Deyo & Diehl 1988, J Gen Intern Med","Age > 50":"Deyo & Diehl 1988, J Gen Intern Med","Failure to improve after 1 month":"Deyo & Diehl 1988, J Gen Intern Med","Fever with back pain and IV drug use":"unsourced (Deyo 1992, JAMA RCE, gives sensitivities only)","Urinary retention":"Deyo 1992, JAMA RCE","Morning stiffness > 30 min, improves with exercise, age < 40":"Rudwaleit 2006, Arthritis Rheum (the 3.1 figure is not reported there; 2 of 4 criteria LR 3.7, 3 of 4 LR 12.4; treat 3.1 as approximate)"}},"sync":{"ask":[{"q":"What were you doing just before: standing, sitting, lying down, or exercising?","why":"Vasovagal syncope needs venous pooling and happens upright; syncope while lying or sitting or during exertion means the heart could not raise output, which is arrhythmia or outflow obstruction.","changes":"Exertional or supine syncope means admission for monitoring and an echocardiogram.","lr":null,"target":"Cardiac syncope","src":"ESC syncope guideline 2018 (high-risk features); Albassam 2019, JAMA RCE"},{"q":"Did you get any warning: feeling hot, sweaty, sick, or your vision closing in?","why":"A prodrome is the autonomic reflex developing over seconds to minutes; an arrhythmia drops cerebral perfusion within seconds, so there is nothing to feel.","changes":"No prodrome with injury from the fall means an ECG, monitoring and often an implantable loop recorder.","lr":null,"target":"Arrhythmia vs vasovagal","src":"Albassam 2019, JAMA RCE (feeling cold before syncope LR 0.16, headache before LR 0.17, mood change LR 0.09 for cardiac cause); Sheldon 2002, JACC"},{"q":"Did your heart race or pound just before you went?","why":"Palpitations immediately before loss of consciousness mean a tachyarrhythmia reduced cardiac output.","changes":"Palpitations before syncope need a 12-lead ECG, monitoring and often an electrophysiology opinion.","lr":null,"target":"Arrhythmia","src":"ESC syncope guideline 2018 (listed high-risk feature; no pooled LR)"},{"q":"How old were you the first time this happened, and do you have atrial fibrillation or known heart disease?","why":"First syncope after 35 and structural or electrical heart disease change the base rate; vasovagal syncope usually declares itself young.","changes":"Known AF or structural heart disease makes cardiac syncope the default and justifies admission.","lr":7.3,"target":"Cardiac syncope","src":"Albassam 2019, JAMA RCE (history of AF or flutter 7.3; age 35 or over at first syncope 3.3; under 35 LR 0.13)"},{"q":"Did anyone see it: how long were you out, what colour were you, and did you jerk?","why":"A witness gives the duration and colour; pallor and brief jerks after collapse are common in syncope (cerebral hypoperfusion myoclonus), whereas cyanosis suggests a cardiac cause and sustained rhythmic jerking a seizure.","changes":"A witnessed cyanosis or prolonged rhythmic convulsion changes the pathway to cardiac or neurology work-up.","lr":6.2,"target":"Cardiac syncope","src":"Albassam 2019, JAMA RCE (witnessed cyanosis LR 6.2)"},{"q":"Did you bite your tongue, and if so which part?","why":"A tonic-clonic seizure clenches the jaw with the tongue displaced sideways, biting the lateral edge; syncope rarely bites, and if it does it is the tip.","changes":"Lateral tongue biting makes seizure the working diagnosis and starts the first-seizure pathway.","lr":7,"target":"Seizure","src":"Brigo 2012, Epilepsy Res (tongue biting sensitivity 33%, specificity 96%); Benbadis 1995, Arch Intern Med"},{"q":"How quickly were you back to normal: seconds, or confused and sleepy for a while?","why":"Cerebral perfusion restores consciousness within seconds in syncope; a post-ictal state reflects neuronal exhaustion and lasts minutes to hours.","changes":"Confusion over five minutes or a headache afterwards points to seizure and away from syncope.","lr":null,"target":"Seizure","src":"Sheldon 2002, JACC (point score: post-event confusion); Albassam 2019, JAMA RCE (inability to remember behaviour before LR 0.25 for cardiac)"},{"q":"Was it after standing a long time, pain, a fright, heat, or a hot crowded room?","why":"These are the classic vasovagal triggers: venous pooling or an emotional stimulus activating the Bezold-Jarisch reflex with bradycardia and vasodilatation.","changes":"A clear trigger with a prodrome and a normal ECG allows discharge with advice.","lr":null,"target":"Vasovagal","src":"ESC syncope guideline 2018; Sheldon 2006, Eur Heart J (diagnostic score)"},{"q":"Did you wet yourself, and did you hurt yourself falling?","why":"Incontinence happens in both and discriminates poorly; injury means there was no warning to protect oneself, which favours an arrhythmic or seizure cause.","changes":"Injury from the fall raises the risk tier and the case for monitoring.","lr":null,"target":"Arrhythmia","src":"Sheldon 2002, JACC (incontinence not discriminating); ESC syncope guideline 2018"},{"q":"Has anyone in your family died suddenly or drowned unexpectedly before 40?","why":"Inherited channelopathies and cardiomyopathies (long QT, Brugada, HCM, ARVC) cause syncope as the warning before sudden death.","changes":"A family history of sudden death means a careful ECG for QT, Brugada pattern and hypertrophy and a cardiology referral.","lr":null,"target":"Inherited arrhythmia","src":"ESC syncope guideline 2018 (high-risk feature)"},{"q":"What medicines do you take, especially for blood pressure, diabetes or mood, and have any changed recently?","why":"Antihypertensives and alpha-blockers cause orthostatic hypotension; QT-prolonging drugs cause torsades; insulin and sulfonylureas cause hypoglycaemia that mimics syncope.","changes":"A new or increased drug means lying and standing blood pressure, a glucose and a QT measurement.","lr":null,"target":"Drug-induced syncope","src":"ESC syncope guideline 2018"},{"q":"Do you drive, and what do you do for work?","why":"Syncope at the wheel or at height kills others; driving regulations and safety-critical work depend on the cause and recurrence risk.","changes":"Unexplained syncope means advice not to drive until investigated and a fitness-to-work discussion.","lr":null,"target":"Safety","src":"DVLA Assessing fitness to drive 2024"}],"lrSrc":{"Syncope on exertion":"unsourced as an LR (high-risk feature in ESC syncope guideline 2018; Albassam 2019 did not pool it)","Palpitations before syncope":"unsourced as an LR (ESC syncope guideline 2018 high-risk feature)","No prodrome, injury on falling":"unsourced as an LR (Albassam 2019, JAMA RCE, gives prodromal features that lower cardiac probability: feeling cold 0.16, headache 0.17)","Lateral tongue biting":"Brigo 2012, Epilepsy Res; Benbadis 1995, Arch Intern Med (any tongue biting LR about 7)","Post-event confusion > 5 min":"unsourced as an LR (Sheldon 2002, JACC, point score item)","Prolonged standing, pain, emotion, heat":"unsourced as an LR (Sheldon 2006, Eur Heart J, point score items)","Age > 65 with structural heart disease":"Albassam 2019, JAMA RCE (known severe structural heart disease LR 3.3 to 4.8; age 35 or over at first syncope 3.3)"}},"dizz":{"ask":[{"q":"Without using the word dizzy, tell me what it actually feels like.","why":"Patients use one word for four experiences: spinning is vestibular, faintness is cerebral hypoperfusion, unsteadiness is cerebellar or proprioceptive, light-headedness is often metabolic or psychological; the mechanism decides the list.","changes":"The quality sorts the patient into the vestibular, cardiovascular or neurological pathway before any examination.","lr":null,"target":"Type of dizziness","src":"Newman-Toker 2007, Mayo Clin Proc (quality is unreliable alone; timing and triggers are better)"},{"q":"Is it there all the time right now, or does it come in attacks, and how long does an attack last?","why":"Continuous vertigo for days is an acute vestibular syndrome (neuritis or posterior stroke); seconds with position is BPPV; minutes to hours with ear symptoms is Ménière's; the duration reflects the pathology, from a canalith settling to a nerve inflamed.","changes":"Continuous vertigo means HINTS examination; episodic positional vertigo means Dix-Hallpike.","lr":null,"target":"Timing-based category","src":"Newman-Toker & Edlow 2015, Neurol Clin (TiTrATE approach)"},{"q":"What sets it off: rolling over in bed, looking up, or standing up?","why":"BPPV is triggered by head movement in the plane of the posterior canal; orthostatic dizziness is triggered by standing because blood pressure falls, so the trigger names the organ.","changes":"Rolling-over vertigo lasting seconds means Dix-Hallpike and Epley; standing-triggered dizziness means lying and standing blood pressures.","lr":null,"target":"BPPV or orthostatic","src":"Bhattacharyya 2017, Otolaryngol Head Neck Surg (BPPV guideline)"},{"q":"Has your hearing changed or do you have ringing or fullness in one ear?","why":"The cochlea and vestibule share the labyrinth and blood supply; unilateral hearing loss with vertigo means labyrinthitis or Ménière's, and sudden deafness is an AICA stroke until proven otherwise.","changes":"New unilateral hearing loss with vertigo means an urgent ENT or stroke assessment rather than vestibular sedatives.","lr":null,"target":"Ménière's, labyrinthitis, AICA stroke","src":"Lee 2009, Stroke (AICA infarction presenting with hearing loss)"},{"q":"Can you stand and walk on your own?","why":"The cerebellum and brainstem keep you upright; vestibular neuritis makes walking unpleasant but possible, whereas a cerebellar stroke often makes unaided standing impossible.","changes":"Inability to stand unaided in acute vertigo means stroke imaging (MRI, since early CT misses most posterior fossa strokes).","lr":null,"target":"Central cause","src":"Carmona 2016, Front Neurol (severe truncal ataxia specificity for stroke); Tarnutzer 2011, CMAJ"},{"q":"Do you have double vision, slurred speech, trouble swallowing, weakness or numbness anywhere?","why":"The vestibular nuclei sit in a crowded brainstem; a lesion big enough to cause vertigo there usually catches a neighbouring tract.","changes":"Any accompanying neurological symptom removes the case from the benign vestibular pathway.","lr":null,"target":"Posterior circulation stroke","src":"Tarnutzer 2011, CMAJ (focal signs present in a minority; HINTS more sensitive)"},{"q":"Do you have a new headache or neck pain with it?","why":"Vertebral artery dissection presents with neck or occipital pain before the stroke; vestibular migraine presents with headache and photophobia.","changes":"Neck pain with vertigo, especially after neck trauma or manipulation, means CT or MR angiography.","lr":null,"target":"Vertebral artery dissection","src":"Gottesman 2012, Neurologist (headache or neck pain in most vertebral dissections)"},{"q":"Are you over 50 with high blood pressure, diabetes, smoking, AF or previous stroke?","why":"Vascular risk raises the base rate of stroke in acute vertigo; vestibular neuritis does not care about risk factors.","changes":"Vascular risk shifts an acute vestibular syndrome towards imaging even when HINTS looks peripheral.","lr":null,"target":"Posterior circulation stroke","src":"Tarnutzer 2011, CMAJ; Kerber 2006, Stroke"},{"q":"Have you started or changed any medicines, and do you drink?","why":"Antihypertensives, anticonvulsants, aminoglycosides and alcohol cause dizziness through hypotension, cerebellar toxicity or ototoxicity.","changes":"A new drug means a dose review and lying and standing blood pressures before any imaging.","lr":null,"target":"Drug-induced dizziness","src":"NICE CKS Vertigo 2023"},{"q":"Have you had migraines, and do you get light sensitivity or visual aura with the dizziness?","why":"Vestibular migraine is the commonest cause of recurrent spontaneous vertigo; the central migraine generator modulates vestibular processing.","changes":"A migraine history with episodic vertigo and headache means migraine prophylaxis rather than vestibular suppressants.","lr":null,"target":"Vestibular migraine","src":"Lempert 2012, J Vestib Res (Bárány Society criteria)"},{"q":"Did you faint or nearly faint, or feel your heart racing with it?","why":"Presyncope with palpitations is arrhythmia reducing cerebral flow; it is cardiac dizziness and needs an ECG, not a vestibular examination.","changes":"Palpitations or near-syncope mean a 12-lead ECG and a syncope-style risk assessment.","lr":null,"target":"Arrhythmia","src":"ESC syncope guideline 2018"},{"q":"Do you feel short of breath, your chest tight, or anxious with it, and does it come with a sense of panic?","why":"Panic and hyperventilation produce light-headedness through hypocapnic cerebral vasoconstriction; it is a diagnosis to make positively, not by default.","changes":"Clear panic features with a normal examination allow a psychological explanation, but only after the vestibular and cardiovascular screens are negative.","lr":null,"target":"Anxiety","src":"Staab 2017, J Vestib Res (persistent postural-perceptual dizziness criteria)"}],"lrSrc":{"Continuous vertigo + normal head impulse test":"unsourced as an LR for history (Kattah 2009, Stroke: HINTS sensitivity 100%, specificity 96% for stroke; normal head impulse is the single most sensitive component)","Vertigo lasting seconds, triggered by rolling over":"unsourced as an LR (diagnostic criterion, Bhattacharyya 2017 BPPV guideline)","Hearing loss or tinnitus with episodes":"unsourced as an LR (Bárány Society Ménière criteria, Lopez-Escamez 2015, J Vestib Res)","Cannot stand unaided":"unsourced as an LR (Carmona 2016, Front Neurol: severe truncal ataxia specificity 100% in one series)","Dizziness on standing with postural drop":"unsourced as an LR (consensus definition: drop of 20 mmHg systolic or 10 diastolic within 3 min, Freeman 2011, Clin Auton Res)"}},"fever":{"ask":[{"q":"How long have you had the fever and does it come and go or stay up?","why":"Duration separates self-limiting viral infection (under a week) from bacterial focus, abscess, endocarditis and non-infectious causes; a relapsing pattern suggests malaria, abscess or lymphoma.","changes":"Fever beyond a week without a source changes the investigation from symptomatic care to cultures, imaging and a PUO approach.","lr":null,"target":"Duration-based category","src":"Petersdorf & Beeson 1961, Medicine (PUO definition)"},{"q":"Have you had proper shaking chills where your teeth chatter and the bed shakes?","why":"Rigors are the hypothalamic set-point rising sharply in response to a bolus of endotoxin or bacteria in the bloodstream; they mark bacteraemia rather than a low-grade viral fever.","changes":"True rigors mean blood cultures before antibiotics and a lower threshold for admission.","lr":4.7,"target":"Bacteraemia","src":"Coburn 2012, JAMA RCE"},{"q":"Let me go through each system: headache or stiff neck, sore throat, cough or breathlessness, burning urine, abdominal pain, diarrhoea, joint pain, rash, or a sore skin area?","why":"Most fevers have a source and the source has a symptom; the review of systems is how you find the organ before examining it.","changes":"A localising symptom directs the examination and the first test (urine dip, chest film, LP) and lets you choose an antibiotic that reaches the site.","lr":null,"target":"Source of infection","src":"NICE NG51 sepsis 2016"},{"q":"Have you travelled abroad in the last year, and where exactly, and did you take malaria tablets?","why":"Falciparum malaria kills within days and can present up to a year after return; vivax relapses for years from liver hypnozoites, so the window is long.","changes":"Any travel to a malaria area in the last year means three thick and thin films or a rapid antigen test the same day, whatever the other symptoms.","lr":null,"target":"Malaria","src":"UK malaria treatment guidelines, Lalloo 2016, J Infect"},{"q":"Do you have an artificial heart valve, a joint replacement, a pacemaker, a line, or do you inject drugs?","why":"Prosthetic material is a biofilm surface that bacteria colonise and antibiotics alone rarely clear; injecting delivers skin flora to the right heart.","changes":"Prosthetic material or injecting with fever means at least three sets of blood cultures and an echocardiogram before empirical antibiotics.","lr":null,"target":"Endocarditis or prosthetic infection","src":"ESC endocarditis guideline 2023 (predisposing conditions in the modified Duke criteria)"},{"q":"Have you had surgery, dental work or a hospital stay recently?","why":"Surgery leaves a collection or a wound; dental work seeds viridans streptococci; hospital stays carry resistant organisms and C. difficile.","changes":"Recent procedures direct imaging to the operative site and change the antibiotic to cover hospital organisms.","lr":null,"target":"Post-procedural infection","src":"NICE NG125 surgical site infection 2019"},{"q":"Are you on chemotherapy, steroids, biologics, do you have HIV, diabetes, or have you had your spleen removed?","why":"Neutropenia removes the host response so fever may be the only sign of overwhelming sepsis; asplenia leaves encapsulated organisms unopposed; steroids blunt fever and signs.","changes":"Neutropenic or asplenic fever means intravenous antibiotics within one hour of arrival, before results.","lr":null,"target":"Neutropenic sepsis","src":"NICE CG151 neutropenic sepsis 2012"},{"q":"Do you have a rash, and does it fade when I press a glass on it?","why":"A non-blanching rash is blood outside vessels: meningococcal endothelial damage and DIC; it can appear in hours.","changes":"A non-blanching rash with fever means immediate parenteral antibiotics and resuscitation before any test.","lr":null,"target":"Meningococcal sepsis","src":"Thompson 2006, Lancet (haemorrhagic rash in 61% of meningococcal disease, median 13 h before admission)"},{"q":"Have you had contact with animals, eaten unpasteurised food, drunk untreated water, or had new sexual partners?","why":"Zoonoses (Q fever, brucella, leptospirosis), food-borne infections and HIV seroconversion each have a specific exposure that no standard culture will find without the clue.","changes":"A specific exposure adds a specific serology or PCR to the screen.","lr":null,"target":"Zoonosis, HIV seroconversion","src":"BIA fever in the returned traveller guideline, Johnston 2009, J Infect"},{"q":"Which medicines have you started in the last few weeks, including antipsychotics and antidepressants?","why":"Drug fever is a hypersensitivity reaction; neuroleptic malignant and serotonin syndromes raise temperature through muscle rigidity and central dysregulation rather than infection.","changes":"A new drug with fever, rigidity or clonus means stopping it and supportive care rather than antibiotics.","lr":null,"target":"Drug fever, NMS, serotonin syndrome","src":"Boyer & Shannon 2005, NEJM (serotonin syndrome); Hunter criteria"},{"q":"Have you had night sweats, weight loss, or swollen glands?","why":"These are the B symptoms of lymphoma and the constitutional symptoms of TB and endocarditis, processes that run for weeks rather than days.","changes":"Constitutional symptoms mean a chest film, LDH, HIV test and a lymph node examination with early biopsy of anything persistent.","lr":null,"target":"Lymphoma, TB, endocarditis","src":"NICE NG12 suspected cancer 2015"},{"q":"Are you confused, breathing faster than usual, or passing less urine?","why":"Altered mentation, tachypnoea and oliguria are end-organ hypoperfusion; they are the clinical face of sepsis rather than simple infection.","changes":"Any of these means a NEWS2 score, lactate and the sepsis pathway within the hour.","lr":null,"target":"Sepsis","src":"Seymour 2016, JAMA (qSOFA); NICE NG51 sepsis 2016"}],"lrSrc":{"Shaking chills (rigors)":"Coburn 2012, JAMA RCE","Travel to a malaria area within 1 year":"unsourced as an LR (UK malaria treatment guidelines, Lalloo 2016, J Infect, mandate testing)","Prosthetic valve or injecting drug use with new murmur":"unsourced as an LR (modified Duke criteria, ESC 2023)","Non-blanching rash":"unsourced as an LR (Thompson 2006, Lancet, reports frequency and timing)","Neutropenia with fever":"unsourced as an LR (NICE CG151 defines the syndrome)"}}},NEW=[{"id":"palp","name":"Palpitations","sys":"cvs","frame":"Pin down what the heart was doing (tap it out), how it started and stopped, what it did to the patient (syncope, chest pain, dyspnoea), the substrate (cardiac disease, family history, drugs, thyroid), and then the context (panic, caffeine, sleep).","ask":[{"q":"Tap out on the table what your heartbeat felt like.","why":"Patients cannot name rhythms but can reproduce them: a regular fast tap is SVT or sinus tachycardia, an irregular jumble is AF, isolated thumps with a pause are ectopics.","changes":"An irregularly irregular tap means a 12-lead ECG and a CHA2DS2-VASc discussion even if the ECG today is sinus.","lr":null,"target":"Rhythm type","src":"Thavendiranathan 2009, JAMA RCE (irregular rhythm perceived LR 1.4 to 2.3 across studies)"},{"q":"Did it start and stop suddenly, like a switch, or build up and fade away?","why":"A re-entrant circuit (AVNRT, AVRT) turns on and off abruptly; sinus tachycardia from anxiety or exertion ramps because the sinus node accelerates gradually.","changes":"Abrupt onset and offset means a re-entrant tachycardia and a cardiology or electrophysiology referral rather than reassurance.","lr":null,"target":"SVT","src":"Thavendiranathan 2009, JAMA RCE (narrative; no pooled LR)"},{"q":"Do you feel a rapid, regular pounding in your neck during an attack?","why":"In AVNRT the atria contract against closed AV valves, firing cannon A waves into the jugular veins; the patient feels a frog-like pounding in the neck.","changes":"This single symptom is near-diagnostic of AVNRT and justifies direct referral for ablation.","lr":177,"target":"AVNRT","src":"Thavendiranathan 2009, JAMA RCE"},{"q":"How long does an attack last?","why":"Attacks under five minutes are more often ectopics or sinus tachycardia; sustained arrhythmias last minutes to hours.","changes":"Brief attacks lower the odds of a significant arrhythmia; sustained attacks need ambulatory monitoring timed to their frequency.","lr":0.38,"target":"Arrhythmia","src":"Thavendiranathan 2009, JAMA RCE (lasting under 5 min LR 0.38)"},{"q":"Do they wake you from sleep or come on at work?","why":"Palpitations that interrupt sleep or occur during work are less likely to be situational anxiety and more likely to be an arrhythmia with a life of its own.","changes":"Nocturnal or at-work palpitations raise the arrhythmia probability and the case for a Holter or event recorder.","lr":2.3,"target":"Arrhythmia","src":"Thavendiranathan 2009, JAMA RCE (affects sleep 2.29; at work 2.17)"},{"q":"Have you fainted, nearly fainted, had chest pain or become breathless with them?","why":"A rhythm fast enough or a ventricle sick enough to drop cardiac output produces syncope; this is the marker of ventricular arrhythmia or structural disease.","changes":"Syncope with palpitations means admission, monitoring and an echocardiogram, not outpatient Holter.","lr":null,"target":"Malignant arrhythmia","src":"ESC supraventricular tachycardia guideline 2019; ESC syncope guideline 2018"},{"q":"Do you have any known heart disease, a previous heart attack or heart failure?","why":"Scar is the substrate for re-entrant ventricular tachycardia; palpitations in a scarred ventricle are dangerous until proven benign.","changes":"Known cardiac disease doubles the odds of arrhythmia and means an echo and specialist review.","lr":2.0,"target":"Arrhythmia","src":"Thavendiranathan 2009, JAMA RCE (LR 2.03)"},{"q":"Has anyone in your family died suddenly or young, or have an inherited heart condition?","why":"Long QT, Brugada, HCM and ARVC are inherited and present with palpitations before they present with sudden death.","changes":"A positive family history means a careful look at the ECG for QT and repolarisation and referral to an inherited cardiac conditions clinic.","lr":null,"target":"Inherited arrhythmia","src":"ESC ventricular arrhythmia guideline 2022"},{"q":"Have you been diagnosed with panic disorder or anxiety?","why":"Panic produces sinus tachycardia with catecholamine release, but it is also where arrhythmias get missed, so it lowers rather than removes the probability.","changes":"A panic history lowers the odds of arrhythmia but does not spare the patient one ECG and, if attacks are typical of SVT, a monitor.","lr":0.26,"target":"Arrhythmia","src":"Thavendiranathan 2009, JAMA RCE"},{"q":"How much caffeine, alcohol and energy drink do you take, and any stimulants, decongestants, salbutamol or thyroid tablets?","why":"These raise sympathetic tone or directly stimulate the myocardium and are the commonest reversible causes of ectopics and sinus tachycardia.","changes":"A clear stimulant pattern means a trial of removal before investigation.","lr":null,"target":"Stimulant-induced","src":"NICE CKS Palpitations 2024"},{"q":"Have you lost weight, felt hot, shaky or had your bowels loosen?","why":"Thyroxine increases beta-receptor density and metabolic rate, driving sinus tachycardia and AF.","changes":"Thyrotoxic features mean TSH before anything else, because treating the thyroid treats the palpitations.","lr":null,"target":"Thyrotoxicosis","src":"NICE NG145 thyroid disease 2019"},{"q":"Are you pregnant, anaemic or have you been unwell with fever or dehydration?","why":"Each raises cardiac output demand and resting heart rate; the palpitations are physiological sinus tachycardia with a cause outside the heart.","changes":"A systemic driver means a full blood count and treating the cause.","lr":null,"target":"Physiological sinus tachycardia","src":"NICE CKS Palpitations 2024"}],"lr":[["Regular rapid pounding in the neck","AVNRT",177],["Visible neck pulsations","AVNRT",2.7],["Palpitations affecting sleep","Arrhythmia",2.3],["Palpitations at work","Arrhythmia",2.2],["Known cardiac disease","Arrhythmia",2.0],["Duration under 5 minutes","Arrhythmia",0.38],["Known panic disorder","Arrhythmia",0.26]],"lrSrc":{"Regular rapid pounding in the neck":"Thavendiranathan 2009, JAMA RCE","Visible neck pulsations":"Thavendiranathan 2009, JAMA RCE (LR 2.68)","Palpitations affecting sleep":"Thavendiranathan 2009, JAMA RCE (LR 2.29)","Palpitations at work":"Thavendiranathan 2009, JAMA RCE (LR 2.17)","Known cardiac disease":"Thavendiranathan 2009, JAMA RCE (LR 2.03)","Duration under 5 minutes":"Thavendiranathan 2009, JAMA RCE","Known panic disorder":"Thavendiranathan 2009, JAMA RCE"},"red":["Syncope or presyncope with palpitations","Palpitations on exertion","Chest pain or breathlessness during attacks","Known structural heart disease or previous MI","Family history of sudden death under 40","Pre-excitation or long QT on the ECG"],"dd":["Sinus tachycardia (anxiety, anaemia, thyrotoxicosis, fever)","Ectopic beats","AVNRT or AVRT","Atrial fibrillation or flutter","Ventricular tachycardia","Drug or stimulant induced","Panic disorder","Hypoglycaemia","Phaeochromocytoma"]},{"id":"cough","name":"Cough and haemoptysis","sys":"resp","frame":"Duration first (under 3 weeks acute, 3 to 8 subacute, over 8 chronic), then what comes up and whether blood, then the three chronic cough causes (asthma, reflux, postnasal drip) and the three cancer questions (smoking, weight, haemoptysis), then the infection and exposure context.","ask":[{"q":"How long have you had the cough?","why":"Acute cough is nearly always infection; a cough over eight weeks is chronic and has a different list (asthma, reflux, upper airway cough syndrome, ACE inhibitor, cancer, bronchiectasis).","changes":"Over three weeks means a chest X-ray; over eight weeks means the chronic cough pathway.","lr":null,"target":"Acute vs chronic","src":"NICE NG12 suspected cancer 2015; BTS cough guideline, Morice 2006, Thorax"},{"q":"Have you coughed up blood, how much, and is it mixed with sputum or pure?","why":"Haemoptysis means a bleeding airway or alveolar source; streaks in purulent sputum are usually bronchitis, pure blood in a smoker is cancer, bronchiectasis or TB until proven otherwise, and massive haemoptysis threatens the airway before the circulation.","changes":"Any haemoptysis over 40 means an urgent chest X-ray and, even if normal, a two-week-wait referral in a smoker.","lr":null,"target":"Lung cancer","src":"Hamilton 2005, Thorax (haemoptysis PPV 2.4% for lung cancer in primary care; Shapley 2010, BJGP)"},{"q":"Do you smoke, how much and for how long, and have you lost weight?","why":"Smoking is the dominant risk for cancer and COPD; weight loss with cough is the signature of malignancy or TB.","changes":"A heavy smoker with weight loss and a new cough gets a chest film and a referral regardless of other findings.","lr":null,"target":"Lung cancer","src":"NICE NG12 suspected cancer 2015"},{"q":"Do you bring up sputum, what colour, and how much each day?","why":"Daily purulent sputum over months is bronchiectasis or chronic bronchitis; sudden purulent sputum with fever is pneumonia or an exacerbation; colour alone is a poor guide to bacterial cause.","changes":"Copious daily purulent sputum means a sputum culture and a CT for bronchiectasis.","lr":null,"target":"Bronchiectasis, pneumonia","src":"Metlay 1997, JAMA RCE (sputum production LR 1.3 for pneumonia)"},{"q":"Do you have fever, shivers, breathlessness or chest pain with it?","why":"These mark lower respiratory infection with parenchymal involvement; pneumonia is unlikely when heart rate, respiratory rate and temperature are all normal.","changes":"Fever with dyspnoea means examination for consolidation and a chest X-ray; normal vital signs make pneumonia unlikely.","lr":null,"target":"Pneumonia","src":"Metlay 1997, JAMA RCE (subjective fever LR 1.7 to 2.1; no vital sign abnormality LR 0.18)"},{"q":"Does the cough come in fits that end with vomiting or a whoop?","why":"Pertussis toxin paralyses the ciliary clearance so coughing comes in exhausting paroxysms; the whoop is forced inspiration through a narrowed glottis and post-tussive vomiting follows the fit.","changes":"Paroxysms with vomiting or whoop in a cough over two weeks mean pertussis PCR or serology and notification.","lr":1.8,"target":"Pertussis","src":"Cornia 2010, JAMA RCE (post-tussive vomiting 1.8; whoop 1.9; absence of paroxysms 0.52)"},{"q":"Is it worse at night or with exercise, do you wheeze, and do you have hay fever or eczema?","why":"Cough-variant asthma is airway hyperresponsiveness without obvious wheeze; nocturnal worsening reflects the circadian fall in cortisol and adrenaline.","changes":"Nocturnal or exertional cough with atopy means peak flow variability or spirometry and a trial of inhaled steroid.","lr":null,"target":"Asthma","src":"Straus 2000, JAMA RCE; NICE NG80 asthma 2017"},{"q":"Do you get heartburn, a sour taste, or cough after meals or lying down?","why":"Refluxed acid stimulates oesophageal vagal afferents that share a cough reflex pathway, and micro-aspiration irritates the larynx.","changes":"Reflux features in chronic cough mean a trial of acid suppression and lifestyle change before further tests.","lr":null,"target":"Reflux cough","src":"Morice 2006, Thorax (BTS cough guideline)"},{"q":"Do you have a blocked nose, postnasal drip or need to clear your throat often?","why":"Secretions dripping onto the larynx trigger the cough reflex; upper airway cough syndrome is one of the three commonest chronic cough causes.","changes":"Postnasal symptoms mean a trial of nasal steroid and antihistamine.","lr":null,"target":"Upper airway cough syndrome","src":"Morice 2006, Thorax"},{"q":"Are you on an ACE inhibitor?","why":"ACE inhibition raises bradykinin and substance P in the airway, sensitising the cough reflex in up to a fifth of users, sometimes months after starting.","changes":"An ACE inhibitor means a switch to an ARB and review in four weeks before any investigation.","lr":null,"target":"ACE inhibitor cough","src":"Dicpinigaitis 2006, Chest (ACCP guideline)"},{"q":"Have you been in contact with TB, lived or travelled in a high-prevalence country, or had night sweats?","why":"TB presents as a chronic cough with constitutional symptoms; reactivation needs a prior exposure and the sweats reflect cytokine-driven fever.","changes":"TB risk means three sputum samples for AFB and a chest film with isolation while waiting.","lr":null,"target":"Tuberculosis","src":"NICE NG33 tuberculosis 2016"},{"q":"What do you do for work, and have you worked with asbestos, silica, dust, birds or farms, and is the cough better away from work?","why":"Occupational lung disease has latency (asbestos 20 to 40 years) or a work-related pattern (occupational asthma, hypersensitivity pneumonitis); the job gives the exposure.","changes":"An exposure history means a CT and respiratory referral, and a work-related pattern means serial peak flows at and away from work.","lr":null,"target":"Occupational lung disease","src":"Malo 1991, Am Rev Respir Dis; BTS pleural disease guideline 2023"},{"q":"Have you had a clot before, had surgery or been immobile, or have a swollen leg?","why":"Pulmonary infarction causes cough and haemoptysis with pleuritic pain; the risk factors are the clot's origin.","changes":"PE risk with haemoptysis means a Wells score and CTPA rather than antibiotics.","lr":null,"target":"PE","src":"Wells 2000, Thromb Haemost (haemoptysis is a Wells criterion)"}],"lr":[["Post-tussive vomiting","Pertussis",1.8],["Inspiratory whoop","Pertussis",1.9],["Absence of paroxysmal cough","Pertussis",0.52],["Subjective fever","Pneumonia",1.9],["All vital signs normal (HR, RR, temperature)","Pneumonia",0.18],["Smoking over 40 pack-years","COPD",8.3]],"lrSrc":{"Post-tussive vomiting":"Cornia 2010, JAMA RCE","Inspiratory whoop":"Cornia 2010, JAMA RCE","Absence of paroxysmal cough":"Cornia 2010, JAMA RCE","Subjective fever":"Metlay 1997, JAMA RCE (LR 1.7 to 2.1)","All vital signs normal (HR, RR, temperature)":"Metlay 1997, JAMA RCE","Smoking over 40 pack-years":"Straus 2000, JAMA RCE"},"red":["Haemoptysis in a smoker or over 40","Massive haemoptysis (over 100 ml or airway compromise)","Weight loss, night sweats, persistent fever","Cough over 3 weeks with hoarseness or chest signs","Stridor or breathlessness at rest","Immunosuppression with cough"],"dd":["Viral bronchitis","Pneumonia","Pertussis","Asthma","COPD","Reflux","Upper airway cough syndrome","ACE inhibitor","Lung cancer","Tuberculosis","Bronchiectasis","PE","Heart failure"]},{"id":"legswell","name":"Leg swelling","sys":"cvs","frame":"One leg or two is the first fork: unilateral is venous obstruction, infection or injury; bilateral is pressure (heart, kidney, liver, drugs) or protein. Then onset speed, pain, skin changes, and the Wells items for DVT.","ask":[{"q":"Is it one leg or both?","why":"A single limb means a local cause: obstructed vein, infected skin, a ruptured cyst or muscle; both legs mean a systemic rise in venous pressure or fall in oncotic pressure, which cannot choose a side.","changes":"Unilateral swelling means a Wells score and D-dimer or ultrasound; bilateral means heart, kidney, liver and drug review.","lr":null,"target":"Local vs systemic","src":"Goodacre 2005, Ann Intern Med (calf asymmetry LR 1.8 for DVT)"},{"q":"How quickly did it come on: hours, days or weeks?","why":"A DVT or cellulitis swells over a day or two; chronic venous insufficiency and lymphoedema evolve over months; sudden swelling after a calf pain during exercise is a muscle tear or ruptured Baker's cyst.","changes":"Acute unilateral swelling is a same-day DVT work-up.","lr":null,"target":"DVT","src":"Wells 1997, Lancet"},{"q":"Have you had cancer, recent surgery, been in bed or on a long journey, or had a clot before?","why":"These are Virchow's triad in history form and the Wells criteria; cancer and prior DVT roughly double or triple the odds.","changes":"Any of these pushes the Wells score up and may move you straight to ultrasound without a D-dimer.","lr":2.7,"target":"DVT","src":"Goodacre 2005, Ann Intern Med (malignancy 2.71, previous DVT 2.25, recent immobilisation 1.98, recent surgery 1.76)"},{"q":"Are you pregnant, recently delivered, or on the pill or HRT?","why":"Oestrogen raises clotting factors and lowers protein S; pregnancy adds venous compression by the uterus, especially of the left iliac vein.","changes":"Oestrogen exposure raises DVT probability; in pregnancy D-dimer is unreliable and ultrasound is the test.","lr":null,"target":"DVT","src":"RCOG Green-top 37b 2015"},{"q":"Is the leg red, hot and painful, and did you have a break in the skin, athlete's foot or an insect bite?","why":"Cellulitis needs a portal of entry; interdigital tinea and small wounds are the commonest, and the inflammation is painful and warm, which a DVT often is not.","changes":"A portal with a hot red spreading area means antibiotics and marking the edge; but one leg can have both cellulitis and DVT.","lr":null,"target":"Cellulitis","src":"Raff & Kroshinsky 2016, JAMA (review)"},{"q":"Is it both legs, and are you short of breath, sleeping propped up, or waking breathless?","why":"Right heart pressure transmits back to the leg veins; the same failure causes orthopnoea and PND from the left side.","changes":"Bilateral oedema with orthopnoea means heart failure work-up: ECG, BNP, echo.","lr":2.3,"target":"Heart failure","src":"Wang 2005, JAMA RCE (peripheral oedema on examination LR 2.3; orthopnoea 2.2)"},{"q":"Which medicines do you take, especially amlodipine or other calcium channel blockers, NSAIDs, steroids, pioglitazone or gabapentin?","why":"Dihydropyridines dilate arterioles more than venules, raising capillary pressure; NSAIDs and glitazones retain sodium; this is the commonest cause of bilateral oedema in primary care.","changes":"A culprit drug means stopping or switching it before diuretics or imaging.","lr":null,"target":"Drug-induced oedema","src":"Makani 2011, Am J Cardiol (amlodipine oedema meta-analysis)"},{"q":"Is your urine frothy, and have you had kidney or liver disease or heavy drinking?","why":"Protein loss in nephrotic syndrome or failure of synthesis in cirrhosis drops plasma oncotic pressure; frothy urine is proteinuria the patient can see.","changes":"Frothy urine or liver risk means a urine dip for protein, albumin and liver function.","lr":null,"target":"Nephrotic syndrome, cirrhosis","src":"NICE CKS Oedema 2023"},{"q":"Does the swelling go down overnight, and do you have varicose veins, brown skin or ulcers at the ankle?","why":"Venous insufficiency swells with gravity and drains lying flat; haemosiderin and lipodermatosclerosis mark years of venous hypertension.","changes":"A chronic venous picture means compression and ulcer care, not a DVT scan, unless it is acutely worse.","lr":null,"target":"Chronic venous insufficiency","src":"NICE CG168 varicose veins 2013"},{"q":"Does the swelling include the top of the foot and toes, and does it pit when you press it?","why":"Lymphoedema is non-pitting protein-rich fluid that involves the dorsum and toes (Stemmer sign); venous and cardiac oedema pit and often spare the toes.","changes":"Non-pitting swelling with toe involvement means lymphoedema and a search for the cause (surgery, radiotherapy, filariasis, cancer).","lr":null,"target":"Lymphoedema","src":"International Society of Lymphology consensus 2020"},{"q":"Did it start with a pop or sharp pain in the calf during activity, or do you have knee arthritis?","why":"A gastrocnemius tear or ruptured Baker's cyst leaks fluid down the calf and mimics DVT exactly; the knee gives the cyst.","changes":"A clear mechanical onset still gets an ultrasound, which can show the cyst or haematoma as well as exclude thrombus.","lr":null,"target":"Ruptured Baker's cyst, muscle tear","src":"Wells 1997, Lancet (alternative diagnosis as likely subtracts 2 points)"},{"q":"Are you breathless, have chest pain or have you coughed blood?","why":"A leg clot that has embolised declares itself in the chest; the leg history is the source and the chest symptoms the consequence.","changes":"Chest symptoms with a swollen leg mean a PE pathway and treatment-dose anticoagulation while waiting.","lr":null,"target":"PE","src":"Wells 2000, Thromb Haemost"}],"lr":[["Active malignancy","DVT",2.7],["Previous DVT","DVT",2.3],["Recent immobilisation","DVT",2.0],["Recent surgery","DVT",1.8],["Calf diameter difference","DVT",1.8],["Wells score high probability","DVT",5.2],["Wells score low probability","DVT",0.25],["Peripheral oedema (bilateral) in a dyspnoeic patient","Heart failure",2.3]],"lrSrc":{"Active malignancy":"Goodacre 2005, Ann Intern Med (LR 2.71)","Previous DVT":"Goodacre 2005, Ann Intern Med (LR 2.25)","Recent immobilisation":"Goodacre 2005, Ann Intern Med (LR 1.98)","Recent surgery":"Goodacre 2005, Ann Intern Med (LR 1.76)","Calf diameter difference":"Goodacre 2005, Ann Intern Med (LR 1.80)","Wells score high probability":"Goodacre 2005, Ann Intern Med","Wells score low probability":"Goodacre 2005, Ann Intern Med","Peripheral oedema (bilateral) in a dyspnoeic patient":"Wang 2005, JAMA RCE"},"red":["Unilateral swelling with cancer, surgery or immobility","Breathlessness, chest pain or haemoptysis with a swollen leg","Rapidly spreading redness, severe pain or blistering (necrotising infection)","Bilateral oedema with orthopnoea or anuria","Phlegmasia (blue, cold, painful leg)"],"dd":["DVT","Cellulitis","Ruptured Baker's cyst","Muscle tear or haematoma","Chronic venous insufficiency","Lymphoedema","Heart failure","Nephrotic syndrome","Cirrhosis","Drug-induced (calcium channel blockers, NSAIDs)","Hypothyroidism","Pelvic mass or iliac compression"]},{"id":"joint","name":"Joint pain","sys":"msk","frame":"Count the joints and clock the onset: one hot joint is septic until the fluid says otherwise; several joints over weeks is inflammatory arthritis; then inflammatory versus mechanical features, distribution, the extra-articular clues (skin, eyes, gut, genitals), and the risk factors for infection and gout.","ask":[{"q":"How many joints are affected, and which ones?","why":"One joint means infection, crystal or trauma; a symmetrical small-joint pattern means rheumatoid; asymmetric large-joint oligoarthritis means spondyloarthritis or reactive arthritis, because each disease has a preferred synovium.","changes":"A single hot joint means aspiration before antibiotics; a polyarthritis means inflammatory markers, rheumatoid factor and anti-CCP.","lr":null,"target":"Pattern of arthritis","src":"ACR/EULAR 2010 rheumatoid arthritis classification (joint pattern scoring)"},{"q":"How quickly did it come on, and is it the first time?","why":"Gout and septic arthritis reach peak within a day; rheumatoid builds over weeks; a first attack in a hot joint cannot be assumed to be gout.","changes":"Onset within 24 hours in a single joint means aspiration for crystals and culture.","lr":null,"target":"Gout vs septic","src":"Janssens 2010, Arch Intern Med (onset within 1 day is a rule item)"},{"q":"Do you have fever, shivers, or feel unwell in yourself?","why":"Bacteraemia seeding a joint produces systemic illness; but fever is absent in up to half of septic joints and present in gout, so it neither confirms nor excludes.","changes":"Fever with a hot joint means blood cultures and aspiration today.","lr":null,"target":"Septic arthritis","src":"Margaretten 2007, JAMA RCE (fever sensitivity 57%)"},{"q":"Do you have diabetes, rheumatoid arthritis, a joint replacement, recent joint surgery or injection, or a skin infection?","why":"Each lowers the barrier to bacterial entry or weakens local defence; a prosthesis with a skin infection multiplies the odds because the biofilm surface is seeded from the skin.","changes":"Any of these with a hot joint moves septic arthritis to the top and means aspiration and an orthopaedic call.","lr":6.9,"target":"Septic arthritis","src":"Margaretten 2007, JAMA RCE (joint surgery within 3 months 6.9; prosthesis plus skin infection 15; diabetes 2.7; RA 2.5 to 3.5; skin infection 2.8; age over 80 3.5)"},{"q":"Have you had gout before, is it the big toe, and do you drink, take diuretics or have kidney disease?","why":"Urate crystallises in cool peripheral joints when serum urate exceeds its solubility; diuretics, alcohol and renal impairment raise urate, and a previous attack is the best predictor of another.","changes":"A classic gout picture allows treatment without aspiration only if the joint is not systemically hot and the diagnosis has been confirmed before.","lr":null,"target":"Gout","src":"Janssens 2010, Arch Intern Med (diagnostic rule: male, previous attack, onset within 1 day, redness, MTP1, hypertension or CVD, urate)"},{"q":"Are your joints stiff in the morning, for how long, and does activity make them better or worse?","why":"Inflammatory synovitis accumulates fluid and cytokines overnight so stiffness lasts over 30 to 60 minutes and eases with movement; osteoarthritis stiffens briefly after rest and hurts with use.","changes":"Morning stiffness over an hour in several joints means early rheumatology referral; brief stiffness with use-related pain means osteoarthritis management.","lr":null,"target":"Inflammatory arthritis","src":"ACR 1987 rheumatoid criteria (morning stiffness over 1 hour); NICE NG100 2018"},{"q":"Did you injure it, and if so how exactly?","why":"The mechanism predicts the structure: twisting with a pop and immediate swelling is a cruciate or meniscus with haemarthrosis; swelling the next day is a lesser injury.","changes":"Immediate swelling after a twist means an X-ray and orthopaedic review for haemarthrosis.","lr":null,"target":"Ligament or meniscal injury","src":"Solomon 2001, JAMA RCE (knee ligament and meniscus examination)"},{"q":"Have you had diarrhoea, a urinary infection, discharge or a new sexual partner in the last month?","why":"Reactive arthritis follows enteric or genital infection by one to four weeks through molecular mimicry; gonococcal arthritis follows sexual exposure directly.","changes":"A preceding infection means stool and genital testing and consideration of gonococcal arthritis with a migratory pattern.","lr":null,"target":"Reactive or gonococcal arthritis","src":"Carter & Hudson 2009, Rheum Dis Clin North Am"},{"q":"Do you have psoriasis, a scaly scalp, nail pitting, mouth ulcers, a rash, sore eyes or back pain?","why":"Psoriatic, lupus and spondyloarthritis declare themselves outside the joints; the skin, nails and eyes are the clue the joint alone cannot give.","changes":"Extra-articular features direct the serology and the referral (dermatology-rheumatology, ophthalmology for uveitis).","lr":null,"target":"Psoriatic arthritis, SLE, spondyloarthritis","src":"CASPAR criteria, Taylor 2006, Arthritis Rheum"},{"q":"Have you had a tick bite or been walking in long grass, and did you get a spreading round rash?","why":"Lyme arthritis presents months after erythema migrans as a large-joint oligoarthritis, usually the knee.","changes":"Tick exposure means Lyme serology before labelling it reactive or idiopathic.","lr":null,"target":"Lyme arthritis","src":"NICE NG95 Lyme disease 2018"},{"q":"Have you lost weight, had night sweats or bone pain that wakes you?","why":"Pain at night and constitutional symptoms suggest tumour, infection or myeloma in or near the joint rather than synovitis.","changes":"Night pain with systemic symptoms means imaging and inflammatory markers rather than a trial of NSAIDs.","lr":null,"target":"Malignancy or osteomyelitis","src":"NICE NG12 suspected cancer 2015"},{"q":"What does your job and sport involve, and which tasks can you no longer do?","why":"Repetitive load and kneeling drive osteoarthritis and bursitis; the functional loss is what decides fitness to work and the adjustments needed.","changes":"A task-specific pattern means ergonomic change and a fit note with restrictions rather than absence.","lr":null,"target":"Work-related musculoskeletal disorder","src":"Palmer 2012, Occup Environ Med (occupational knee osteoarthritis review)"}],"lr":[["Joint surgery within the past 3 months","Septic arthritis",6.9],["Hip or knee prosthesis with overlying skin infection","Septic arthritis",15],["Diabetes","Septic arthritis",2.7],["Rheumatoid arthritis","Septic arthritis",2.5],["Skin infection","Septic arthritis",2.8],["Age over 80","Septic arthritis",3.5],["Synovial fluid WBC over 50,000/µL","Septic arthritis",7.7],["Inflammatory back pain, 2 of 4 criteria","Axial spondyloarthritis",3.7]],"lrSrc":{"Joint surgery within the past 3 months":"Margaretten 2007, JAMA RCE","Hip or knee prosthesis with overlying skin infection":"Margaretten 2007, JAMA RCE","Diabetes":"Margaretten 2007, JAMA RCE","Rheumatoid arthritis":"Margaretten 2007, JAMA RCE (2.5; some summaries quote 3.5)","Skin infection":"Margaretten 2007, JAMA RCE","Age over 80":"Margaretten 2007, JAMA RCE","Synovial fluid WBC over 50,000/µL":"Margaretten 2007, JAMA RCE","Inflammatory back pain, 2 of 4 criteria":"Rudwaleit 2006, Arthritis Rheum"},"red":["Single hot swollen joint (septic until aspirated)","Fever with joint pain","Prosthetic joint with pain or fever","Immunosuppression or injecting drug use","Night pain with weight loss","Inability to bear weight after trauma"],"dd":["Septic arthritis","Gout","Pseudogout","Trauma and haemarthrosis","Osteoarthritis","Rheumatoid arthritis","Psoriatic arthritis","Reactive arthritis","Spondyloarthritis","Viral arthritis (parvovirus, hepatitis)","Lyme arthritis","SLE","Polymyalgia rheumatica"]},{"id":"rash","name":"Rash","sys":"derm","frame":"The dermatology history is a timeline: when and where it started, how it spread, what a single lesion does over its life, what it feels like, then drugs in the last eight weeks, contacts and exposures, systemic symptoms, and the sick-or-not question for the acute rash.","ask":[{"q":"Where did it start, and how has it spread since?","why":"The pattern of spread is the pathology: a viral exanthem starts at the head and descends, a drug eruption starts on the trunk and is symmetrical, contact dermatitis follows the shape of what touched the skin, shingles follows a dermatome.","changes":"A dermatomal or contact-shaped distribution gives the diagnosis before any test; a descending exanthem with fever means a viral screen and infection control.","lr":null,"target":"Distribution-based diagnosis","src":"Rook's Textbook of Dermatology, 9th ed (principles of the dermatological history)"},{"q":"Describe one spot: what does it start as, what does it become, and how long does it last?","why":"The evolution of a single lesion is the morphology the examination will see later; a wheal that lasts under 24 hours is urticaria, a vesicle that crusts is herpes, a papule that scales is psoriasis or eczema.","changes":"Wheals under 24 hours mean urticaria and no biopsy; a fixed lesion over 24 hours with bruising means urticarial vasculitis and a biopsy.","lr":null,"target":"Urticaria vs vasculitis","src":"EAACI/GA2LEN urticaria guideline, Zuberbier 2022, Allergy"},{"q":"Does it itch, hurt or burn?","why":"Itch is histamine, cytokines or bile salts (urticaria, eczema, scabies, cholestasis); pain is inflammation of deeper tissue or nerve (cellulitis, shingles, Sweet syndrome); a painful or tender widespread rash with skin that sloughs is an emergency.","changes":"Skin pain or tenderness with a widespread rash means a Nikolsky check and urgent dermatology for SJS/TEN or staphylococcal scalded skin.","lr":null,"target":"Severe cutaneous reaction","src":"BAD guidelines for SJS/TEN, Creamer 2016, Br J Dermatol"},{"q":"Which medicines have you started or changed in the last eight weeks, including antibiotics, anticonvulsants, allopurinol and anything over the counter or herbal?","why":"Most drug eruptions appear one to three weeks after starting; DRESS can take eight weeks; the drug is the cause in a large share of new symmetrical rashes in adults.","changes":"A new drug in the window means stopping it and checking for fever, lymphadenopathy, eosinophilia and liver involvement.","lr":null,"target":"Drug eruption","src":"Roujeau & Stern 1994, NEJM (severe adverse cutaneous reactions)"},{"q":"Do you feel unwell, with fever, sore throat, mouth ulcers, joint pain or sore eyes?","why":"Systemic symptoms separate a skin-only problem from a systemic disease showing in the skin: meningococcaemia, Kawasaki, lupus, vasculitis, SJS.","changes":"Fever with a rash means examining the mucosae and checking for a non-blanching component now.","lr":null,"target":"Systemic illness with rash","src":"Thompson 2006, Lancet (meningococcal disease features)"},{"q":"Does the rash fade when you press a glass on it?","why":"A non-blanching rash is extravasated red cells: vasculitis, thrombocytopenia, or meningococcal endothelial damage and DIC.","changes":"A non-blanching rash with fever means parenteral antibiotics and resuscitation; without fever it means a platelet count and urine dip for vasculitis.","lr":null,"target":"Purpura","src":"Thompson 2006, Lancet (haemorrhagic rash in 61% of meningococcal disease)"},{"q":"Does anyone at home itch, and is your itch worst at night?","why":"Scabies mites spread by prolonged skin contact and burrow at night when the host is warm; household itch is the clue that one patient cannot give.","changes":"Household itch means treating the whole household with permethrin on the same day.","lr":null,"target":"Scabies","src":"IACS consensus criteria, Engelman 2020, Br J Dermatol"},{"q":"What do you do for work and as hobbies, and what touches your hands: gloves, cement, hair dye, plants, nickel, cleaning products?","why":"Contact dermatitis is either irritant (wet work, detergents) or allergic (chromate, nickel, rubber accelerators, fragrance); the hands and the job give the allergen.","changes":"A work-related pattern with improvement on holiday means patch testing and an occupational dermatitis plan, not just steroid cream.","lr":null,"target":"Occupational contact dermatitis","src":"BOHRF occupational contact dermatitis guideline, Nicholson 2010, Contact Dermatitis"},{"q":"Is the rash better on holiday or days off and worse through the working week?","why":"Removal of the occupational irritant or allergen lets the skin barrier recover; the weekly rhythm is the fingerprint of occupational dermatitis.","changes":"A work-related rhythm means reporting, workplace assessment and patch testing.","lr":null,"target":"Occupational dermatitis","src":"Nicholson 2010, Contact Dermatitis (BOHRF)"},{"q":"Have you used any creams on it already, especially steroid creams?","why":"Topical steroids change the appearance: tinea becomes tinea incognito, scabies loses its burrows, and impetigo spreads; the prior treatment explains the atypical look.","changes":"Steroid-modified rashes need skin scrapings for fungus and a scabies search before further steroid.","lr":null,"target":"Tinea incognito","src":"Rook's Textbook of Dermatology, 9th ed"},{"q":"Have you had new sexual partners, and is there a rash on your palms and soles?","why":"Secondary syphilis produces a non-itchy copper rash that characteristically involves palms and soles; HIV seroconversion gives a maculopapular rash with fever.","changes":"Palm and sole involvement or a new partner means syphilis and HIV serology.","lr":null,"target":"Secondary syphilis, HIV seroconversion","src":"BASHH syphilis guideline 2015"},{"q":"Have you travelled, been bitten, or been in contact with animals or children with rashes?","why":"Travel brings dengue, rickettsia and cutaneous larva migrans; animals bring ringworm; children bring measles, parvovirus and hand, foot and mouth.","changes":"An exposure means a specific serology or scraping and infection control if measles is possible.","lr":null,"target":"Infectious exanthem","src":"UKHSA measles guidance 2024"},{"q":"For a mole: has it changed in size, shape or colour, does it bleed or itch, and how much sun and sunburn have you had?","why":"Melanoma grows and changes; a patient-reported change is the single most useful historical item and is why the E of ABCDE is evolution.","changes":"A changing pigmented lesion means dermoscopy and a two-week-wait referral.","lr":null,"target":"Melanoma","src":"Whited & Grichnik 1998, JAMA RCE (ABCD features; change in size reported by most melanoma patients); NICE NG12 2015 (7-point checklist)"},{"q":"How is it affecting your sleep, your work and your mood?","why":"Skin disease disables through itch, sleep loss and stigma; the Dermatology Life Quality Index captures what the rash alone cannot, and it determines the treatment threshold for systemic therapy.","changes":"A high DLQI justifies escalation to systemic treatment and a fit note with adjustments.","lr":null,"target":"Impact","src":"Finlay & Khan 1994, Clin Exp Dermatol (DLQI)"}],"lr":[["Both eyes glued shut in the morning (for the red eye with rash around it)","Bacterial conjunctivitis",null],["Haemorrhagic non-blanching rash with fever","Meningococcal disease",null],["Asymmetry, border irregularity, colour variation, diameter over 6 mm (ABCD, any)","Melanoma",null],["Clinician-reported change in a pigmented lesion","Melanoma",null]],"lrSrc":{"Both eyes glued shut in the morning (for the red eye with rash around it)":"unsourced as an LR (Rietveld 2004, BMJ: odds ratio 15)","Haemorrhagic non-blanching rash with fever":"unsourced as an LR (Thompson 2006, Lancet: present in 61% of cases, median 13 h before admission)","Asymmetry, border irregularity, colour variation, diameter over 6 mm (ABCD, any)":"unsourced as an LR (Whited & Grichnik 1998, JAMA RCE: ABCD sensitivity 92 to 100%, specificity 98% in one study; no pooled LR)","Clinician-reported change in a pigmented lesion":"unsourced as an LR (Whited & Grichnik 1998, JAMA RCE; MacKie 7-point checklist)"},"red":["Non-blanching rash with fever","Skin pain, blistering or sloughing, mucosal involvement (SJS/TEN)","Rash with fever, facial swelling and lymphadenopathy after a new drug (DRESS)","Rapidly spreading painful erythema out of proportion to signs (necrotising fasciitis)","Angio-oedema with urticaria and breathing difficulty","Changing pigmented lesion"],"dd":["Eczema (atopic, contact, irritant)","Psoriasis","Urticaria","Drug eruption","Viral exanthem","Scabies","Tinea","Cellulitis or impetigo","Shingles","Vasculitis or purpura","Secondary syphilis","Meningococcal disease","SJS/TEN or DRESS","Melanoma or skin cancer"]},{"id":"weak","name":"Weakness or numbness","sys":"neuro","frame":"Time course first (seconds to minutes is vascular, hours to days is inflammatory or compressive, weeks is tumour or degeneration), then the anatomical question (one side, both legs, a glove, a dermatome, proximal or distal, fatigable), then bladder and sensory level, then the stroke clock and the anticoagulant.","ask":[{"q":"Exactly when did it start, and was it at its worst immediately or did it spread over minutes, hours or days?","why":"An artery occludes in seconds and the deficit is maximal at once; a migraine aura marches over minutes; inflammation and compression evolve over hours to days; tumour over weeks. The tempo is the pathology.","changes":"Sudden maximal onset within the last 4.5 hours means the stroke pathway and a CT now; a marching onset points to migraine or seizure.","lr":null,"target":"Stroke vs mimic","src":"Goldstein & Simel 2005, JAMA RCE; NICE NG128 stroke 2019"},{"q":"Has your face drooped, is one arm weak, or is your speech slurred or muddled?","why":"These are the FAST items; the middle cerebral artery territory carries face, arm and language, so one of the three is present in most anterior circulation strokes.","changes":"Any one of the three in a sudden-onset deficit means a stroke call; all three absent makes stroke less likely but does not exclude posterior circulation stroke.","lr":5.5,"target":"Stroke","src":"Goldstein & Simel 2005, JAMA RCE (any one of facial paresis, arm drift, abnormal speech LR 5.5; none present LR 0.39)"},{"q":"Is it one side of the body, both legs, both hands and feet, or a patch?","why":"Hemibody is brain or brainstem; both legs with a level is spinal cord; glove-and-stocking is peripheral nerve; a dermatome or a single nerve territory is a root or a nerve. The distribution localises the lesion before the examination.","changes":"Bilateral leg weakness means a sensory level search and urgent spinal imaging; a hemibody pattern means brain imaging.","lr":null,"target":"Localisation","src":"McGee, Evidence-Based Physical Diagnosis, 5th ed (localisation chapters)"},{"q":"Any change in passing urine or opening your bowels, or numbness around your back passage?","why":"The sacral fibres for bladder, bowel and saddle sensation are the first casualties of a central cord or cauda equina lesion; retention is the earliest objective sign.","changes":"Bladder symptoms with limb weakness mean a bladder scan, rectal examination and emergency MRI.","lr":18,"target":"Cauda equina or cord compression","src":"Deyo 1992, JAMA RCE (urinary retention LR 18 for cauda equina)"},{"q":"Is the weakness worse at the end of the day or after repeated use, and does your speech get slurred or your eyelids droop with talking?","why":"Myasthenia depletes acetylcholine receptor reserve with repeated use, so weakness is fatigable and worst in the evening; the ocular and bulbar muscles declare it first.","changes":"Fatigable weakness means acetylcholine receptor antibodies and a neurology referral, and a check of swallow and breathing.","lr":4.5,"target":"Myasthenia gravis","src":"Scherer 2005, JAMA RCE (speech becoming unintelligible during prolonged speaking LR 4.5)"},{"q":"Did the numbness or weakness start in your feet and climb upwards, and did you have diarrhoea or a chest infection in the last few weeks?","why":"Guillain-Barré is a post-infectious demyelination that ascends over days; Campylobacter and respiratory infections are the usual triggers through molecular mimicry.","changes":"Ascending weakness means admission, serial spirometry and a lumbar puncture, because respiratory failure can follow within days.","lr":null,"target":"Guillain-Barré syndrome","src":"Brighton criteria, Fokke 2014, Brain"},{"q":"Do you have double vision, difficulty swallowing, vertigo or unsteadiness with it?","why":"Cranial nerve and cerebellar symptoms with limb weakness localise to the brainstem and the posterior circulation, which FAST misses.","changes":"Brainstem symptoms mean the stroke pathway even with a normal FAST and an MRI rather than CT alone.","lr":null,"target":"Posterior circulation stroke","src":"Tarnutzer 2011, CMAJ"},{"q":"Does the numbness in your hand wake you at night, and do you shake it to get relief?","why":"Carpal tunnel pressure rises with wrist flexion in sleep; the flick to relieve it is the patient's own decompression.","changes":"Nocturnal median-territory numbness means a hand symptom diagram, Phalen's test and a splint before nerve conduction studies.","lr":null,"target":"Carpal tunnel syndrome","src":"D'Arcy & McGee 2000, JAMA RCE (classic or probable hand diagram LR 2.4; flick sign poorly studied)"},{"q":"Did your face weakness include the forehead, and can you still wrinkle your brow?","why":"The forehead has bilateral cortical input, so a central (stroke) lesion spares it; a peripheral facial nerve lesion (Bell's) takes the whole side.","changes":"Forehead sparing means stroke work-up; forehead involvement means Bell's palsy, steroids within 72 hours and eye protection.","lr":null,"target":"Bell's palsy vs stroke","src":"Baugh 2013, Otolaryngol Head Neck Surg (AAO-HNS Bell's palsy guideline)"},{"q":"Have you had similar episodes before that recovered, or problems with vision, balance or bladder months or years ago?","why":"Relapsing and remitting deficits separated in time and space are the clinical definition of multiple sclerosis; optic neuritis is the commonest first attack.","changes":"A relapsing pattern in a young adult means MRI with contrast and neurology referral rather than a stroke pathway.","lr":null,"target":"Multiple sclerosis","src":"McDonald criteria 2017, Thompson 2018, Lancet Neurol"},{"q":"Do you take anticoagulants, have atrial fibrillation, high blood pressure, diabetes, or have you had a stroke or TIA before?","why":"Anticoagulation changes a sudden deficit from likely ischaemia to possible haemorrhage, and the vascular risk factors set the base rate for stroke.","changes":"Anticoagulant use means urgent CT and reversal discussion; AF means anticoagulation after the stroke is characterised.","lr":null,"target":"Stroke, haemorrhage","src":"NICE NG128 stroke 2019"},{"q":"Do you drink heavily, have diabetes, take isoniazid or chemotherapy, or eat a restricted diet?","why":"These are the causes of a length-dependent peripheral neuropathy: toxic, metabolic and nutritional (B12, thiamine).","changes":"A neuropathy history means glucose, B12 and liver function, and nerve conduction studies if unexplained.","lr":null,"target":"Peripheral neuropathy","src":"England 2009, Neurology (AAN practice parameter on distal symmetric polyneuropathy)"},{"q":"Did you have a headache, neck pain or neck manipulation before the weakness?","why":"Carotid or vertebral dissection causes pain before the stroke as the vessel wall tears, often after trivial neck trauma in a younger patient.","changes":"Neck pain preceding a deficit means CT or MR angiography of the neck vessels.","lr":null,"target":"Cervical artery dissection","src":"Debette & Leys 2009, Lancet Neurol"}],"lr":[["Any one of facial paresis, arm drift or abnormal speech","Stroke",5.5],["None of facial paresis, arm drift or abnormal speech","Stroke",0.39],["Speech becomes unintelligible during prolonged speaking","Myasthenia gravis",4.5],["Urinary retention","Cauda equina",18],["Classic or probable hand symptom diagram","Carpal tunnel syndrome",2.4],["Ice test positive (ptosis improves)","Myasthenia gravis",24]],"lrSrc":{"Any one of facial paresis, arm drift or abnormal speech":"Goldstein & Simel 2005, JAMA RCE","None of facial paresis, arm drift or abnormal speech":"Goldstein & Simel 2005, JAMA RCE","Speech becomes unintelligible during prolonged speaking":"Scherer 2005, JAMA RCE","Urinary retention":"Deyo 1992, JAMA RCE","Classic or probable hand symptom diagram":"D'Arcy & McGee 2000, JAMA RCE","Ice test positive (ptosis improves)":"Scherer 2005, JAMA RCE"},"red":["Sudden focal deficit within the thrombolysis window","Bilateral leg weakness, sensory level or bladder involvement","Ascending weakness with breathlessness or swallowing difficulty","Fatigable bulbar weakness (myasthenic crisis)","Deficit on anticoagulants","Headache or neck pain preceding the deficit"],"dd":["Ischaemic stroke or TIA","Intracerebral haemorrhage","Migraine with aura","Todd's paresis after seizure","Multiple sclerosis","Spinal cord compression or cauda equina","Guillain-Barré syndrome","Myasthenia gravis","Peripheral neuropathy","Entrapment neuropathy (carpal tunnel, ulnar, peroneal)","Bell's palsy","Functional neurological disorder","Hypoglycaemia"]},{"id":"dysuria","name":"Dysuria and urinary symptoms","sys":"abd","frame":"In women the aim is to separate cystitis from vaginitis and urethritis (ask about discharge and irritation) and then to find pyelonephritis (flank pain, fever, rigors); in men every UTI is complicated, so ask about prostate symptoms and urethritis; in both, haematuria without infection is cancer until shown otherwise.","ask":[{"q":"Does it burn when you pass urine, and are you going more often or in a hurry?","why":"Dysuria and frequency are bladder and urethral mucosal inflammation; each raises the probability of UTI modestly on its own but together, without vaginal symptoms, they are close to diagnostic.","changes":"Dysuria and frequency without discharge or irritation give a probability over 90% and justify empirical treatment without a dipstick.","lr":1.5,"target":"UTI","src":"Bent 2002, JAMA RCE (dysuria 1.5; frequency 1.8; dysuria plus frequency without vaginal discharge or irritation 24.6)"},{"q":"Do you have any vaginal discharge or irritation?","why":"Vaginitis and cervicitis cause external dysuria as urine crosses inflamed vulval skin; their presence shifts the diagnosis away from the bladder to the vagina or an STI.","changes":"Discharge or irritation means a vaginal examination and swabs rather than antibiotics for cystitis.","lr":0.3,"target":"UTI","src":"Bent 2002, JAMA RCE (discharge 0.3; irritation 0.2)"},{"q":"Is there blood in your urine?","why":"Haemorrhagic cystitis is common in bacterial infection and visible haematuria is the most specific symptom for UTI; but haematuria that persists after treatment is bladder or kidney cancer until excluded.","changes":"Haematuria with infective symptoms supports treatment; haematuria without infection, or persisting after it, means urology referral.","lr":2.0,"target":"UTI","src":"Bent 2002, JAMA RCE; Giesen 2010, BMC Fam Pract"},{"q":"Do you have pain in your back or side, fever or shivering?","why":"Flank pain, fever and rigors mean the infection has ascended to the renal parenchyma, which changes the antibiotic, its duration and the risk of bacteraemia.","changes":"Flank pain with fever means a longer course, cultures, and admission if vomiting or unwell.","lr":1.6,"target":"UTI (upper tract)","src":"Bent 2002, JAMA RCE (back pain 1.6; CVA tenderness 1.7); Coburn 2012, JAMA RCE (rigors LR 4.7 for bacteraemia)"},{"q":"Have you had this before, and does this feel the same as your previous infections?","why":"Women with recurrent UTI recognise the syndrome; self-diagnosis has a measurable LR and underpins self-start treatment.","changes":"Reliable self-diagnosis allows a self-start antibiotic plan.","lr":4.0,"target":"UTI","src":"Bent 2002, JAMA RCE (self-diagnosis in women with recurrent UTI)"},{"q":"Could you be pregnant?","why":"Asymptomatic and symptomatic bacteriuria in pregnancy progresses to pyelonephritis and preterm labour more often; the antibiotic choice also changes.","changes":"Pregnancy means a culture, treatment of bacteriuria, and avoiding trimethoprim in the first trimester and nitrofurantoin at term.","lr":null,"target":"UTI in pregnancy","src":"NICE NG109 lower UTI 2018"},{"q":"For men: is the stream weak, do you dribble, strain, or get up at night, and is there perineal or rectal pain?","why":"A UTI in a man usually has a reason: an obstructing prostate leaves residual urine that infects, and prostatitis gives perineal pain and systemic upset.","changes":"Obstructive symptoms mean a post-void residual and prostate examination; perineal pain and fever mean a four-week course for prostatitis.","lr":null,"target":"Prostatitis, obstruction","src":"NICE NG110 prostatitis 2018; EAU urological infections guideline 2024"},{"q":"Have you had a new sexual partner, urethral discharge, or testicular pain?","why":"Chlamydia and gonorrhoea cause urethritis that mimics cystitis, with sterile pyuria; epididymo-orchitis in young men is usually sexually acquired.","changes":"STI risk means a first-void urine NAAT and partner notification rather than cystitis treatment.","lr":null,"target":"Urethritis, STI","src":"BASHH urethritis guideline 2015"},{"q":"Do you have a catheter, kidney stones, diabetes or a weakened immune system?","why":"These make the infection complicated: catheters carry biofilm, stones harbour organisms, diabetes impairs neutrophil function and predisposes to emphysematous pyelonephritis.","changes":"A complicating factor means a culture before treatment and a longer or broader course.","lr":null,"target":"Complicated UTI","src":"EAU urological infections guideline 2024"},{"q":"Which antibiotics have you had in the last three months, and have you been in hospital or abroad?","why":"Recent antibiotics, hospital exposure and travel to high-resistance areas select for ESBL and resistant organisms, which change the empirical choice.","changes":"Recent antibiotic exposure means a culture and a different first-line agent.","lr":null,"target":"Resistant organism","src":"NICE NG109 lower UTI 2018"},{"q":"Are you confused, off your food or more unsteady than usual, and is anyone saying you are not yourself?","why":"In older people UTI often presents with delirium, falls or functional decline rather than dysuria; but asymptomatic bacteriuria is common and a positive dipstick in a confused patient is not proof.","changes":"Delirium with urinary symptoms means a culture and a search for other causes before attributing it to the urine.","lr":null,"target":"UTI in the older patient","src":"SIGN 160 UTI 2020; PHE diagnosis of UTI 2020 (do not dipstick over 65)"},{"q":"Have you lost weight, smoked, or worked with dyes, rubber or in painting?","why":"Painless haematuria with these risks is urothelial cancer; aromatic amines in dyes and rubber are classic occupational bladder carcinogens.","changes":"Visible haematuria over 45 or persistent non-visible haematuria with risk factors means a two-week-wait urology referral.","lr":null,"target":"Bladder cancer","src":"NICE NG12 suspected cancer 2015; Cumberbatch 2015, JAMA Oncol (occupational bladder cancer)"}],"lr":[["Dysuria","UTI",1.5],["Frequency","UTI",1.8],["Haematuria","UTI",2.0],["Back pain","UTI",1.6],["Vaginal discharge (history)","UTI",0.3],["Vaginal irritation (history)","UTI",0.2],["Dysuria and frequency with no discharge or irritation","UTI",24.6],["Self-diagnosis in recurrent UTI","UTI",4.0]],"lrSrc":{"Dysuria":"Bent 2002, JAMA RCE","Frequency":"Bent 2002, JAMA RCE","Haematuria":"Bent 2002, JAMA RCE","Back pain":"Bent 2002, JAMA RCE","Vaginal discharge (history)":"Bent 2002, JAMA RCE","Vaginal irritation (history)":"Bent 2002, JAMA RCE","Dysuria and frequency with no discharge or irritation":"Bent 2002, JAMA RCE (single study)","Self-diagnosis in recurrent UTI":"Bent 2002, JAMA RCE (single study)"},"red":["Fever with flank pain, rigors or vomiting (pyelonephritis, urosepsis)","Infection with obstruction or a stone (needs decompression)","Visible haematuria over 45 or painless haematuria","Acute retention","Pregnancy with upper tract symptoms","Delirium or sepsis in the older patient"],"dd":["Cystitis","Pyelonephritis","Urethritis (chlamydia, gonorrhoea)","Vaginitis or candidiasis","Prostatitis","Epididymo-orchitis","Urinary stone","Interstitial cystitis","Bladder cancer","Atrophic vaginitis","Drug-induced cystitis (cyclophosphamide, ketamine)"]},{"id":"womabdo","name":"Abdominal pain in women and early pregnancy","sys":"abd","frame":"Establish pregnancy status before anything else, then the ectopic questions (bleeding, shoulder tip pain, risk factors, syncope), then the PID questions (discharge, dyspareunia, new partner, IUD), then torsion and ovarian cyst, and never let a positive test or a prior scan close the ectopic question until an intrauterine pregnancy has been seen.","ask":[{"q":"When was your last period, was it normal, and could you be pregnant?","why":"A missed or abnormal period with pain is ectopic pregnancy until the scan shows an intrauterine sac; history and examination cannot exclude it and the test is cheap.","changes":"Every woman of reproductive age with abdominal pain has a pregnancy test before any other decision.","lr":null,"target":"Ectopic pregnancy","src":"Crochet 2013, JAMA RCE (symptom LRs below 1.5; transvaginal ultrasound is the decisive test)"},{"q":"Have you had any vaginal bleeding, and how much?","why":"Ectopic bleeding is decidual shedding from falling hCG support, usually light and dark; heavy bleeding with clots suggests miscarriage. Neither pattern is reliable enough to decide.","changes":"Bleeding in early pregnancy means an early pregnancy unit assessment with transvaginal ultrasound and hCG.","lr":null,"target":"Ectopic or miscarriage","src":"Crochet 2013, JAMA RCE; NICE NG126 ectopic pregnancy and miscarriage 2019"},{"q":"Do you have pain at the tip of your shoulder, or have you fainted or felt faint?","why":"Blood in the peritoneum irritates the diaphragm and refers to C4; syncope means enough haemoperitoneum to drop cardiac output. Both mean the ectopic has ruptured.","changes":"Shoulder tip pain or syncope in early pregnancy means resuscitation, two large cannulae and the gynaecologist now.","lr":null,"target":"Ruptured ectopic","src":"NICE NG126 2019 (listed as symptoms of ectopic pregnancy)"},{"q":"Have you had an ectopic before, tubal surgery, a coil in place, pelvic infection, or fertility treatment?","why":"Each damages or bypasses tubal transport; a previous ectopic and tubal surgery carry the highest recurrence, and an IUD prevents intrauterine more than tubal implantation, so a pregnancy with a coil in situ is disproportionately ectopic.","changes":"Risk factors lower the threshold for ultrasound and for admission while hCG is tracked.","lr":null,"target":"Ectopic pregnancy","src":"Ankum 1996, Fertil Steril (meta-analysis of risk factors: previous ectopic OR 8.3, tubal surgery OR 21, IUD in situ OR 4.2 to 45)"},{"q":"Do you have a vaginal discharge, pain during sex, bleeding after sex or between periods?","why":"Cervicitis and endometritis cause discharge, dyspareunia and contact bleeding; PID is a clinical diagnosis made on these with pelvic tenderness, because waiting for swabs loses tubes.","changes":"These symptoms with lower abdominal pain and tenderness mean empirical PID treatment and swabs, not waiting for results.","lr":null,"target":"PID","src":"BASHH PID guideline 2019; CDC STI treatment guidelines 2021 (minimum clinical criteria)"},{"q":"Have you had a new sexual partner in the last three months, or a partner with symptoms?","why":"Chlamydia and gonorrhoea ascend from the cervix within weeks of acquisition; a new partner is the exposure that makes PID likely.","changes":"A new partner with pelvic pain means PID treatment, STI screen, and partner notification.","lr":null,"target":"PID","src":"BASHH PID guideline 2019"},{"q":"Did the pain start suddenly on one side, with vomiting, and is it coming in waves?","why":"Ovarian torsion twists the pedicle and produces sudden severe unilateral pain with vomiting from peritoneal and autonomic stimulation; a haemorrhagic or ruptured cyst gives a similar onset, often mid-cycle or after sex.","changes":"Sudden unilateral pain with vomiting means urgent ultrasound with Doppler and gynaecology review, because the ovary dies within hours.","lr":null,"target":"Ovarian torsion or cyst accident","src":"Houry & Abbott 2001, Ann Emerg Med (nausea and vomiting in 70% of torsion); RCOG Green-top 62"},{"q":"Is the pain related to your cycle: with periods, mid-cycle, or during sex deep inside?","why":"Endometriosis causes cyclical pain and deep dyspareunia from ectopic endometrium bleeding into the pelvis; mittelschmerz is follicular rupture mid-cycle.","changes":"Cyclical pain means a gynaecology referral for endometriosis rather than repeated emergency scans.","lr":null,"target":"Endometriosis","src":"NICE NG73 endometriosis 2017"},{"q":"Do you have fever, shivers, or feel unwell in yourself?","why":"Fever with pelvic pain means tubo-ovarian abscess, septic miscarriage or appendicitis; uncomplicated ectopic and torsion are usually afebrile.","changes":"Fever with pelvic pain means blood cultures, intravenous antibiotics and imaging for an abscess.","lr":null,"target":"Tubo-ovarian abscess","src":"BASHH PID guideline 2019"},{"q":"Have you had any recent procedure: a termination, miscarriage, coil insertion, or instrumentation?","why":"Instrumentation breaches the cervical barrier and seeds the uterus; PID risk peaks in the three weeks after IUD insertion, and retained products after miscarriage or termination become infected.","changes":"A recent procedure with pain and fever means endometritis treatment and ultrasound for retained products.","lr":null,"target":"Post-procedural infection","src":"Farley 1992, Lancet (IUD and PID risk confined to first 20 days)"},{"q":"Where exactly is the pain, and has it moved from the middle to the right side?","why":"Appendicitis is the commonest surgical cause of pelvic pain in young women and is missed because the pelvic differential is long; migration to the right iliac fossa is its signature.","changes":"Migration with anorexia and nausea means a surgical review alongside the gynaecological assessment.","lr":3.2,"target":"Appendicitis","src":"Wagner 1996, JAMA RCE (migration LR 3.18)"},{"q":"Are you safe at home, and is anyone hurting you?","why":"Pelvic pain, STIs and unplanned pregnancy cluster with intimate partner violence; the consultation about the pelvis is the one where asking is natural and expected.","changes":"A disclosure changes the safety plan and the documentation, and may change who is allowed in the room.","lr":null,"target":"Intimate partner violence","src":"NICE PH50 domestic violence 2014; WHO 2013 clinical guidelines"}],"lr":[["Cervical motion tenderness","Ectopic pregnancy",4.9],["Peritoneal signs","Ectopic pregnancy",4.2],["Adnexal mass","Ectopic pregnancy",2.4],["Any single symptom (pain, bleeding)","Ectopic pregnancy",1.5],["Bedside transvaginal ultrasound showing no intrauterine pregnancy","Ectopic pregnancy",111],["Pain migrating to the right lower quadrant","Appendicitis",3.2]],"lrSrc":{"Cervical motion tenderness":"Crochet 2013, JAMA RCE","Peritoneal signs":"Crochet 2013, JAMA RCE (LR 4.2 to 4.5)","Adnexal mass":"Crochet 2013, JAMA RCE","Any single symptom (pain, bleeding)":"Crochet 2013, JAMA RCE (all symptom LRs below 1.5)","Bedside transvaginal ultrasound showing no intrauterine pregnancy":"Crochet 2013, JAMA RCE","Pain migrating to the right lower quadrant":"Wagner 1996, JAMA RCE"},"red":["Positive pregnancy test with pain and no intrauterine pregnancy seen","Shoulder tip pain or syncope in early pregnancy","Haemodynamic instability","Sudden severe unilateral pain with vomiting (torsion)","Fever with pelvic peritonism (abscess)","Pain migrating to the right iliac fossa"],"dd":["Ectopic pregnancy","Miscarriage","Pelvic inflammatory disease","Tubo-ovarian abscess","Ovarian torsion","Ovarian cyst rupture or haemorrhage","Appendicitis","Endometriosis","Mittelschmerz","UTI or pyelonephritis","Renal colic","Fibroid degeneration"]},{"id":"redeye","name":"Red eye","sys":"hn","frame":"Separate the three dangerous red eyes (angle closure, keratitis, iritis and scleritis) from conjunctivitis with four history items: pain, photophobia, reduced vision and contact lenses. Then characterise the discharge and the exposure.","ask":[{"q":"Is the eye painful, or just gritty and uncomfortable?","why":"Deep aching pain comes from the ciliary body, iris or sclera, which are innervated by the trigeminal nerve; conjunctiva produces grittiness, not pain.","changes":"True pain means same-day slit lamp assessment, not topical antibiotics.","lr":null,"target":"Serious cause","src":"Narayana & McGee 2015, Am J Med (systematic review)"},{"q":"Does bright light hurt your eye?","why":"Photophobia is ciliary spasm from an inflamed iris or cornea; the light constricts the pupil and the inflamed iris hurts. Consensual photophobia, pain in the affected eye when light is shone into the other, is particularly specific.","changes":"Photophobia means urgent ophthalmology for iritis or keratitis and no steroid drops until herpes is excluded.","lr":8.3,"target":"Serious cause (iritis, keratitis)","src":"Narayana & McGee 2015, Am J Med (direct photophobia 8.3; indirect photophobia 28.8; finger-to-nose convergence photophobia 21.4)"},{"q":"Has your vision gone blurred or dim, and does it clear when you blink?","why":"Reduced vision means the cornea, anterior chamber or deeper structures are involved; blurring that clears with a blink is tear film and discharge, which is benign.","changes":"Persistent reduced acuity means an ophthalmology referral the same day.","lr":null,"target":"Serious cause","src":"Narayana & McGee 2015, Am J Med; NICE CKS Red eye 2024"},{"q":"Do you wear contact lenses, and did you sleep or swim in them?","why":"Lenses abrade the epithelium and carry Pseudomonas and Acanthamoeba; a red painful eye in a lens wearer is microbial keratitis until the slit lamp says otherwise, and it can perforate in days.","changes":"A lens wearer with a painful red eye is sent to eye casualty today with the lens and case for culture.","lr":null,"target":"Microbial keratitis","src":"Stapleton 2008, Ophthalmology (lens-related keratitis risk); NICE CKS 2024"},{"q":"Did it come on with severe pain, a headache, vomiting and haloes around lights, in the evening or in dim light?","why":"Acute angle closure follows pupil mid-dilation in the dark; the iris blocks the trabecular meshwork, pressure rises over 50 mmHg, the cornea becomes oedematous (haloes) and the vagal response causes vomiting.","changes":"This story means immediate ophthalmology for pressure lowering; the eye can be blind within hours.","lr":null,"target":"Acute angle-closure glaucoma","src":"NICE CKS Glaucoma 2024; Narayana & McGee 2015 (anisocoria LR 6.5 for serious cause)"},{"q":"Were both eyes stuck shut with discharge this morning?","why":"Bacterial conjunctivitis produces purulent exudate that dries on the lashes overnight; viral and allergic conjunctivitis produce watery or stringy discharge that does not glue.","changes":"Bilateral morning gluing makes bacterial conjunctivitis likely enough to consider a topical antibiotic; its absence argues against one.","lr":null,"target":"Bacterial conjunctivitis","src":"Rietveld 2004, BMJ (both eyes glued OR 15); Narayana & McGee 2015 (absence of morning gluing LR 0.3)"},{"q":"Does it itch, and do you get hay fever, or have you had this before?","why":"Itch is histamine from conjunctival mast cells, the hallmark of allergic conjunctivitis; recurrence and itch each argue against bacterial infection.","changes":"Itch with watery discharge means antihistamine or mast cell stabiliser drops, not antibiotics.","lr":null,"target":"Allergic conjunctivitis","src":"Rietveld 2004, BMJ (itching and previous conjunctivitis predict a non-bacterial cause)"},{"q":"Did you have a cold or sore throat, and did the other eye follow a few days later?","why":"Adenoviral conjunctivitis follows an upper respiratory infection and spreads to the second eye; it is highly contagious and self-limiting.","changes":"A viral picture means hygiene advice and no antibiotic, with return if pain or photophobia develops (keratitis).","lr":null,"target":"Viral conjunctivitis","src":"Azari & Barney 2013, JAMA (conjunctivitis review)"},{"q":"Did anything go into the eye: grinding, hammering, chemicals, a branch?","why":"High-velocity metal means a possible intraocular foreign body; chemicals, especially alkali, saponify the cornea within minutes; vegetable matter brings fungal keratitis.","changes":"Chemical exposure means irrigation before anything else, including history; hammering or grinding means an X-ray or CT for a foreign body.","lr":null,"target":"Trauma, chemical injury, foreign body","src":"NICE CKS Eye injuries 2024"},{"q":"Do you have back pain and stiffness, bowel disease, psoriasis, cold sores, or a known autoimmune condition?","why":"Anterior uveitis is the eye manifestation of HLA-B27 spondyloarthritis and inflammatory bowel disease; scleritis accompanies rheumatoid and vasculitis; herpes simplex causes dendritic keratitis.","changes":"A systemic association raises iritis or scleritis above conjunctivitis and means a dilated examination and the appropriate referral.","lr":null,"target":"Uveitis or scleritis","src":"Rosenbaum 2008, NEJM (uveitis and spondyloarthritis)"},{"q":"Have you been using any eye drops, especially steroids, or had recent eye surgery?","why":"Topical steroids mask infection and raise pressure; a red eye within weeks of intraocular surgery is endophthalmitis until proven otherwise.","changes":"Recent surgery with a red painful eye means same-day ophthalmology; steroid drop use means checking pressure and for herpetic disease.","lr":null,"target":"Endophthalmitis","src":"NICE CKS Red eye 2024"},{"q":"Is the redness all over the white, or in a ring around the coloured part?","why":"Diffuse redness with the lids involved is conjunctival; a ring of injection at the limbus (ciliary flush) means the ciliary vessels are dilated by iris or corneal inflammation.","changes":"A limbal pattern on the patient's description or your look means the serious pathway.","lr":null,"target":"Iritis or keratitis","src":"Narayana & McGee 2015, Am J Med"}],"lr":[["Photophobia on direct light","Serious cause of red eye",8.3],["Photophobia on indirect (consensual) light","Serious cause of red eye",28.8],["Photophobia on finger-to-nose convergence","Serious cause of red eye",21.4],["Anisocoria over 1 mm, smaller pupil on the red side","Serious cause of red eye",6.5],["Absence of morning gluing","Bacterial conjunctivitis",0.3],["Both eyes glued shut in the morning","Bacterial conjunctivitis",null]],"lrSrc":{"Photophobia on direct light":"Narayana & McGee 2015, Am J Med","Photophobia on indirect (consensual) light":"Narayana & McGee 2015, Am J Med (wide confidence interval)","Photophobia on finger-to-nose convergence":"Narayana & McGee 2015, Am J Med","Anisocoria over 1 mm, smaller pupil on the red side":"Narayana & McGee 2015, Am J Med","Absence of morning gluing":"Narayana & McGee 2015, Am J Med","Both eyes glued shut in the morning":"unsourced as an LR (Rietveld 2004, BMJ: odds ratio 15)"},"red":["Pain, photophobia or reduced vision","Contact lens wearer with a painful red eye","Severe pain with headache, vomiting and haloes (angle closure)","Fixed mid-dilated or unequal pupil","Chemical injury or high-velocity foreign body","Red eye after intraocular surgery"],"dd":["Viral conjunctivitis","Bacterial conjunctivitis","Allergic conjunctivitis","Dry eye and blepharitis","Subconjunctival haemorrhage","Episcleritis","Scleritis","Anterior uveitis","Keratitis (microbial, herpetic)","Acute angle-closure glaucoma","Corneal abrasion or foreign body","Endophthalmitis"]},{"id":"throat","name":"Sore throat","sys":"hn","frame":"Two jobs: decide the probability of streptococcal infection (Centor or FeverPAIN, which are history and examination combined) and find the airway and abscess emergencies (drooling, trismus, stridor, muffled voice, one-sided swelling). Then the glandular fever and immunosuppression questions.","ask":[{"q":"Have you had a fever, and are you coughing?","why":"Streptococcal pharyngitis produces fever with little cough; a viral infection involves the lower airway and causes cough. Fever and absence of cough are two of the four Centor items.","changes":"Fever without cough adds Centor points and moves towards testing or treating; a prominent cough argues for a virus and no antibiotic.","lr":null,"target":"Streptococcal pharyngitis","src":"Ebell 2000, JAMA RCE; Centor 1981, Med Decis Making; Aalbers 2011, BMC Med (Centor meta-analysis)"},{"q":"Are the glands in your neck swollen and tender, and have you seen white spots on your tonsils?","why":"Tender anterior cervical nodes and tonsillar exudate are the other two Centor items; exudate is neutrophils and fibrin on infected crypts.","changes":"Three or four Centor points justify a rapid antigen test or empirical antibiotics; zero or one point does not.","lr":3.4,"target":"Streptococcal pharyngitis","src":"Ebell 2000, JAMA RCE (tonsillar exudate 3.4; pharyngeal exudate 2.1)"},{"q":"Has anyone at home or at work had a confirmed strep throat in the last two weeks?","why":"Group A streptococcus spreads by droplets within households; recent exposure raises the pre-test probability.","changes":"Known exposure adds to the clinical score and lowers the threshold to test.","lr":1.9,"target":"Streptococcal pharyngitis","src":"Ebell 2000, JAMA RCE"},{"q":"Can you swallow your own saliva, open your mouth fully, and does your voice sound different?","why":"Drooling means the patient cannot swallow, trismus means the pterygoid muscles are inflamed by a peritonsillar abscess, and a hot-potato voice means supraglottic swelling; these are the airway and abscess signs.","changes":"Any of these means an ENT or emergency assessment now, not oral antibiotics and home.","lr":null,"target":"Quinsy, epiglottitis, deep neck infection","src":"NICE NG84 sore throat 2018 (red flags); SIGN 117"},{"q":"Is one side much worse than the other?","why":"Pharyngitis is symmetrical; a unilateral swelling with pain referred to the ear is a peritonsillar abscess forming between tonsil and constrictor muscle.","changes":"Unilateral swelling means ENT review for aspiration or drainage.","lr":null,"target":"Peritonsillar abscess","src":"NICE NG84 sore throat 2018"},{"q":"Are you having any difficulty breathing, or a noise when you breathe in?","why":"Stridor is turbulent flow through a critically narrowed upper airway; in adults it usually means epiglottitis or a deep neck abscess, and examining the throat can precipitate obstruction.","changes":"Stridor means no tongue depressor, sit upright, call for airway help and ENT.","lr":null,"target":"Epiglottitis, airway obstruction","src":"NICE NG84 sore throat 2018"},{"q":"How long has it been going on, and are you exhausted with it, with glands in your neck, armpits or groin?","why":"Glandular fever runs for weeks with generalised lymphadenopathy and fatigue; the Epstein-Barr virus infects B cells throughout the lymphoid system rather than only the tonsils.","changes":"A prolonged course with generalised nodes means a monospot or EBV serology, splenic precautions and avoiding amoxicillin.","lr":null,"target":"Infectious mononucleosis","src":"Ebell 2004, Am Fam Physician (mononucleosis review: posterior cervical nodes, splenomegaly, atypical lymphocytes)"},{"q":"Are you on chemotherapy, carbimazole, clozapine or other drugs that can lower your white cells?","why":"Agranulocytosis presents as a sore throat with fever because the neutrophils that normally contain oral flora are gone; the sore throat is the first sign of a dangerous drug reaction.","changes":"A sore throat on carbimazole or clozapine means an urgent full blood count the same day and stopping the drug until it is known.","lr":null,"target":"Drug-induced agranulocytosis","src":"MHRA Drug Safety Update (carbimazole, clozapine)"},{"q":"Have you had a new sexual partner, oral sex, or any genital symptoms?","why":"Gonococcal pharyngitis and primary HIV infection both present as a sore throat; HIV seroconversion adds rash, fever and lymphadenopathy.","changes":"Sexual risk means a throat NAAT for gonorrhoea and an HIV test.","lr":null,"target":"Gonococcal pharyngitis, HIV seroconversion","src":"BASHH gonorrhoea guideline 2019"},{"q":"Have you had a rash with it, especially a fine sandpaper rash, or a sore red tongue?","why":"Scarlet fever is group A streptococcus with an erythrogenic toxin; the rash and strawberry tongue make the bacterial diagnosis clinically and the disease is notifiable.","changes":"A sandpaper rash means antibiotics, notification, and school exclusion for 24 hours.","lr":null,"target":"Scarlet fever","src":"UKHSA scarlet fever guidance 2023"},{"q":"Does the pain go to your ear, have you lost weight, or has the sore throat lasted more than three weeks, and do you smoke or drink?","why":"A persistent unilateral sore throat with otalgia in a smoker or drinker is oropharyngeal cancer until proven otherwise; HPV-related tumours occur in younger non-smokers too.","changes":"A sore throat over three weeks or unilateral persistent symptoms means a two-week-wait ENT referral.","lr":null,"target":"Head and neck cancer","src":"NICE NG12 suspected cancer 2015"},{"q":"Have you had rheumatic fever, a heart valve problem, or do you have a weakened immune system?","why":"Streptococcal infection in a patient with prior rheumatic fever risks recurrence and valve damage; immunosuppression changes the organisms and the threshold for treatment.","changes":"A rheumatic or immunosuppressed history lowers the threshold for antibiotics regardless of the score.","lr":null,"target":"Complications of streptococcal infection","src":"NICE NG84 sore throat 2018"}],"lr":[["Tonsillar exudate","Streptococcal pharyngitis",3.4],["Pharyngeal exudate","Streptococcal pharyngitis",2.1],["Known streptococcal exposure in the past 2 weeks","Streptococcal pharyngitis",1.9],["Centor score 4","Streptococcal pharyngitis",6.3],["Centor score 0","Streptococcal pharyngitis",0.16],["Centor score 1","Streptococcal pharyngitis",0.3]],"lrSrc":{"Tonsillar exudate":"Ebell 2000, JAMA RCE","Pharyngeal exudate":"Ebell 2000, JAMA RCE","Known streptococcal exposure in the past 2 weeks":"Ebell 2000, JAMA RCE","Centor score 4":"Ebell 2000, JAMA RCE (Centor 4 LR 6.3); Aalbers 2011, BMC Med","Centor score 0":"Ebell 2000, JAMA RCE; Aalbers 2011, BMC Med","Centor score 1":"Ebell 2000, JAMA RCE (LR 0.3); Aalbers 2011, BMC Med"},"red":["Stridor or respiratory distress","Drooling or inability to swallow saliva","Trismus, muffled voice or unilateral swelling (quinsy)","Sore throat on carbimazole, clozapine or chemotherapy","Neck stiffness, severe systemic illness","Sore throat over 3 weeks or unilateral with otalgia"],"dd":["Viral pharyngitis","Streptococcal tonsillitis","Infectious mononucleosis","Peritonsillar abscess","Epiglottitis or supraglottitis","Retropharyngeal or parapharyngeal abscess","Scarlet fever","Gonococcal pharyngitis","Primary HIV infection","Agranulocytosis","Oropharyngeal cancer","Reflux laryngopharyngitis"]},{"id":"trauma","name":"Trauma","sys":"gen","frame":"AMPLE (Allergies, Medications, Past history, Last meal, Events) in the primary survey, then mechanism in enough detail to predict the injuries (speed, restraint, height, direction, energy), then the decision-rule questions for head and neck imaging, then anticoagulants and the reason for the fall.","ask":[{"q":"Are you allergic to anything?","why":"Antibiotics, analgesia, contrast and anaesthetic drugs will follow within the hour; the allergy history is the one piece of history that must precede treatment.","changes":"A documented allergy changes the antibiotic, the contrast plan and the anaesthetic.","lr":null,"target":"AMPLE: Allergies","src":"ATLS 10th ed, American College of Surgeons 2018"},{"q":"What medicines do you take, especially blood thinners, beta-blockers, steroids and insulin?","why":"Anticoagulants turn a minor head injury into a bleeding risk and mandate CT; beta-blockers hide the tachycardia of haemorrhage; steroids blunt the stress response; insulin predicts hypoglycaemia as the cause of the crash.","changes":"Anticoagulant use means CT head within eight hours regardless of other findings and early reversal if bleeding; beta-blockade means not trusting the pulse.","lr":null,"target":"AMPLE: Medications","src":"NICE NG232 head injury 2023 (anticoagulant criterion); ATLS 10th ed"},{"q":"What medical problems do you have, and have you had surgery before?","why":"Cardiac disease limits the reserve for blood loss; previous abdominal surgery changes the abdominal examination; a pacemaker, a prosthetic valve or osteoporosis each change what the injury means.","changes":"Comorbidity lowers the threshold for admission and imaging and changes the fluid strategy.","lr":null,"target":"AMPLE: Past history","src":"ATLS 10th ed"},{"q":"When did you last eat or drink?","why":"A full stomach raises aspiration risk at induction; the anaesthetist needs it and the surgeon needs it to plan timing.","changes":"A recent meal means rapid sequence induction and influences whether surgery is immediate or delayed.","lr":null,"target":"AMPLE: Last meal","src":"ATLS 10th ed"},{"q":"Tell me exactly what happened: how fast, how far, what hit what, and were you thrown or trapped?","why":"Energy transfer predicts injury: a fall over 1 m or five stairs, a vehicle over 100 km/h, ejection, rollover, a pedestrian or cyclist struck, and an axial load to the head each carry specific patterns, and the dangerous mechanisms are criteria in the imaging rules.","changes":"A dangerous mechanism means cervical spine imaging under the Canadian C-spine rule and a lower threshold for CT of head and torso even with a reassuring examination.","lr":3.0,"target":"Severe intracranial injury","src":"Easter 2015, JAMA RCE (pedestrian struck by motor vehicle LR 3.0 to 4.3); Stiell 2001, JAMA (Canadian C-spine rule dangerous mechanism)"},{"q":"Did you black out, and can you remember the moments before and after?","why":"Loss of consciousness and amnesia mark a brain injury severe enough to disrupt the reticular formation or hippocampal encoding; amnesia over 30 minutes before impact is a Canadian CT head rule criterion, though neither item alone is strongly predictive.","changes":"Amnesia over 30 minutes or loss of consciousness with a dangerous mechanism or age over 65 means a CT head.","lr":null,"target":"Intracranial injury","src":"Stiell 2001, Lancet (Canadian CT head rule); Easter 2015, JAMA RCE (loss of consciousness and headache minimally useful alone)"},{"q":"Have you vomited, and how many times?","why":"Vomiting after head injury is a brainstem response to raised intracranial pressure or a direct vestibular insult; two or more episodes are a rule criterion.","changes":"Two or more vomits mean a CT head within an hour.","lr":3.6,"target":"Severe intracranial injury","src":"Easter 2015, JAMA RCE (vomiting, especially 2 or more episodes, LR 3.6)"},{"q":"Have you had a fit since the injury?","why":"A post-traumatic seizure means cortical irritation by blood or contusion.","changes":"A seizure after head injury means CT within an hour.","lr":2.5,"target":"Severe intracranial injury","src":"Easter 2015, JAMA RCE (LR 2.5)"},{"q":"How old are you, and do you have osteoporosis?","why":"Age over 65 raises the odds of intracranial bleeding (bridging veins, atrophy) and of cervical fracture from low-energy falls; the C-spine rule removes the clinical-clearance option above 65.","changes":"Over 65 means CT head on lower thresholds and imaging of the neck rather than clinical clearance.","lr":2.3,"target":"Severe intracranial injury","src":"Easter 2015, JAMA RCE (age 65 or over LR 2.3); Stiell 2001, JAMA"},{"q":"Do you have any neck pain, and could you turn your head 45 degrees each way before I ask you to?","why":"Midline tenderness and inability to rotate are Canadian C-spine rule items; a patient with a low-risk mechanism, no midline tenderness and active rotation can be cleared without imaging.","changes":"Midline tenderness, a dangerous mechanism, paraesthesia or inability to rotate means imaging; the rule's low-risk criteria allow safe clinical clearance.","lr":null,"target":"Cervical spine injury","src":"Stiell 2001, JAMA (Canadian C-spine rule sensitivity 100%); Stiell 2003, NEJM"},{"q":"Do you have tingling, numbness or weakness in your arms or legs?","why":"Paraesthesia in the limbs after trauma means cord or root involvement and is a high-risk item that removes the clinical clearance pathway.","changes":"Any limb paraesthesia means spinal immobilisation and imaging.","lr":null,"target":"Spinal cord injury","src":"Stiell 2001, JAMA (Canadian C-spine rule)"},{"q":"Why did you fall or crash: did you trip, or did you feel faint, dizzy or have chest pain first?","why":"A medical event (syncope, arrhythmia, hypoglycaemia, stroke, seizure) often causes the trauma; treating the fracture and missing the arrhythmia sends the patient home to fall again.","changes":"An unexplained collapse before the injury means an ECG, glucose and a syncope assessment alongside the trauma work-up.","lr":null,"target":"Medical cause of trauma","src":"NICE CG161 falls 2013; ESC syncope guideline 2018"},{"q":"Have you had alcohol or drugs today?","why":"Intoxication masks pain and neurological signs, makes the examination unreliable, and is itself a criterion for imaging when the examination cannot be trusted.","changes":"Intoxication lowers the threshold for imaging and means observation until the examination is reliable.","lr":null,"target":"Unreliable examination","src":"NEXUS criteria, Hoffman 2000, NEJM (intoxication precludes clinical clearance)"},{"q":"Is this injury consistent with what you have told me, and is anyone hurting you?","why":"Injuries inconsistent with the mechanism, delayed presentation, multiple injuries of different ages and a controlling companion are the markers of assault and domestic abuse; the trauma consultation is the opportunity to ask alone.","changes":"Inconsistency or a disclosure changes documentation, safeguarding and whether the patient is seen alone.","lr":null,"target":"Non-accidental injury","src":"NICE PH50 domestic violence 2014; RCEM domestic abuse best practice 2021"}],"lr":[["Skull fracture signs (open, depressed, Battle sign, haemotympanum, CSF leak, raccoon eyes)","Severe intracranial injury",16],["GCS 13 (versus 14 to 15)","Severe intracranial injury",4.9],["Vomiting, two or more episodes","Severe intracranial injury",3.6],["Pedestrian struck by a motor vehicle","Severe intracranial injury",3.0],["Post-traumatic seizure","Severe intracranial injury",2.5],["Age 65 or over","Severe intracranial injury",2.3],["Any decline in GCS","Severe intracranial injury",3.4]],"lrSrc":{"Skull fracture signs (open, depressed, Battle sign, haemotympanum, CSF leak, raccoon eyes)":"Easter 2015, JAMA RCE (pooled LR 16)","GCS 13 (versus 14 to 15)":"Easter 2015, JAMA RCE","Vomiting, two or more episodes":"Easter 2015, JAMA RCE","Pedestrian struck by a motor vehicle":"Easter 2015, JAMA RCE (LR 3.0 to 4.3)","Post-traumatic seizure":"Easter 2015, JAMA RCE","Age 65 or over":"Easter 2015, JAMA RCE","Any decline in GCS":"Easter 2015, JAMA RCE (LR range 3.4 to 16)"},"red":["GCS under 15 at two hours, or any fall in GCS","Signs of skull base or depressed fracture","Two or more vomits, seizure, or focal deficit","Anticoagulant use with head injury","Dangerous mechanism (fall over 1 m or 5 stairs, high-speed, ejection, pedestrian struck, axial load)","Limb paraesthesia or midline cervical tenderness","Unexplained collapse before the injury"],"dd":["Intracranial haemorrhage (extradural, subdural, contusion)","Concussion","Cervical spine fracture or ligamentous injury","Spinal cord injury","Pneumothorax, haemothorax, rib fractures","Splenic or hepatic injury","Pelvic fracture with haemorrhage","Long bone fracture","Medical cause of collapse (syncope, hypoglycaemia, seizure, stroke)","Non-accidental injury"]},{"id":"febchild","name":"The febrile child","sys":"gen","frame":"Age first (under 3 months is a different pathway), then the NICE traffic light domains in order: colour, activity, respiratory, circulation and hydration, and the specific red flags (non-blanching rash, bulging fontanelle, neck stiffness, focal signs, fits). Then the source questions and the parent's instinct, which is itself evidence.","ask":[{"q":"How old is the baby or child, and were they born early or had any problems at birth?","why":"Under three months the immune system is immature, bacteraemia is more likely, and the signs are non-specific; prematurity and neonatal problems add risk. Age sets the pathway before any symptom.","changes":"Fever of 38 or over in an infant under three months means referral for blood, urine and often CSF cultures regardless of appearance.","lr":null,"target":"Serious bacterial infection in infancy","src":"NICE NG143 fever in under 5s 2019"},{"q":"How are they in themselves: do they smile, play, respond to you, and can you wake them normally?","why":"A child fighting a serious infection withdraws; decreased activity, no smile, and difficulty waking are amber and red traffic light items because cytokines and hypoperfusion suppress the brain first.","changes":"Not responding normally or hard to rouse means the red pathway: urgent assessment and admission.","lr":null,"target":"Serious illness","src":"NICE NG143 2019 (activity domain); Van den Bruel 2010, Lancet"},{"q":"What colour are they: pale, mottled, ashen or blue?","why":"Colour reflects peripheral perfusion; mottling and cyanosis mean vasoconstriction or hypoxia and are among the strongest single red flags.","changes":"Pallor reported by the parent is amber; mottling or cyanosis is red and means immediate assessment.","lr":null,"target":"Serious infection","src":"Van den Bruel 2010, Lancet (cyanosis LR 2.7 to 52; poor peripheral perfusion LR 2.4 to 39)"},{"q":"Are they breathing fast, grunting, or pulling in under the ribs?","why":"Tachypnoea and recession are the work of breathing against stiff lungs (pneumonia, bronchiolitis) or the compensation for acidosis in sepsis; grunting is the child creating their own PEEP.","changes":"Grunting or marked recession is red; tachypnoea above the age threshold is amber and means chest examination and saturations.","lr":null,"target":"Pneumonia or sepsis","src":"NICE NG143 2019; Van den Bruel 2010, Lancet (rapid breathing LR 1.3 to 9.8)"},{"q":"How many wet nappies in the last 12 hours, are they drinking, and are their lips and tongue dry?","why":"Reduced urine output and dry mucosae mean dehydration or shock; a child who will not feed is both losing fluid and showing sickness behaviour.","changes":"Reduced urine output or poor feeding is amber; reduced skin turgor is red and means fluid assessment.","lr":null,"target":"Dehydration and shock","src":"NICE NG143 2019 (circulation and hydration domain)"},{"q":"Is there a rash, and does it fade when you press a glass against it?","why":"A non-blanching rash is extravasated blood from meningococcal endothelial damage; it can appear hours before collapse.","changes":"A non-blanching rash means parenteral antibiotics and emergency transfer now.","lr":null,"target":"Meningococcal disease","src":"Van den Bruel 2010, Lancet (petechial rash LR 6.2 to 84); Thompson 2006, Lancet"},{"q":"Have they had a fit, is the soft spot on the head bulging, or are they holding their neck stiff?","why":"Seizure, a bulging fontanelle and neck stiffness are meningeal and intracranial signs; they are red flags because meningitis in infancy rarely gives a clearer clue.","changes":"Any of these means immediate hospital assessment and consideration of lumbar puncture and antibiotics.","lr":null,"target":"Meningitis","src":"NICE NG143 2019 (red features)"},{"q":"How high has the temperature been, and how long has the fever lasted?","why":"Temperature of 39 or over in a 3 to 6 month old is amber and 38 or over under 3 months is red; a fever over five days raises Kawasaki disease, in which coronary aneurysms form if untreated.","changes":"Fever over five days means a Kawasaki check (conjunctivitis, lips, rash, hands and feet, lymph node) and referral.","lr":null,"target":"Kawasaki disease","src":"NICE NG143 2019; McCrindle 2017, Circulation (AHA Kawasaki statement)"},{"q":"Where do you think the infection is: ear pulling, cough, sore throat, vomiting or diarrhoea, pain passing urine, a swollen joint, or a sore limb they will not use?","why":"Most febrile children have a source and the source has a symptom; a limb they will not use is septic arthritis or osteomyelitis until proven otherwise.","changes":"A localising symptom directs the examination; no source in an infant means a urine sample before antibiotics.","lr":null,"target":"Source of infection","src":"NICE NG143 2019 (symptoms and signs of specific illnesses)"},{"q":"Are their vaccinations up to date, and have they been in contact with anyone with measles, chickenpox or meningitis?","why":"Vaccination removes Hib, pneumococcal and meningococcal risk in large part; an unvaccinated child has a different base rate, and contact with a notifiable disease changes the differential.","changes":"Incomplete vaccination lowers the threshold for investigation; a meningococcal contact means prophylaxis.","lr":null,"target":"Vaccine-preventable infection","src":"NICE NG143 2019; UKHSA Green Book"},{"q":"Have they travelled abroad recently?","why":"Malaria, typhoid and dengue present as fever without a source; a travel history is the only way to think of them.","changes":"Travel to a malaria area means blood films regardless of how well the child looks.","lr":null,"target":"Imported infection","src":"RCPCH and UK malaria guidelines, Lalloo 2016, J Infect"},{"q":"Do they have any long-term condition, immune problem or recent antibiotics?","why":"Immunodeficiency, sickle cell disease and recent antibiotics change the organisms and the reliability of the signs.","changes":"Immunocompromise means the low-threshold pathway and blood cultures.","lr":null,"target":"Complicated infection","src":"NICE NG143 2019"},{"q":"What is your gut feeling: is this different from their usual illnesses, and are you worried?","why":"Parental concern that this illness is different has a measured likelihood ratio comparable to any single sign; the parent has thousands of hours of baseline the clinician lacks.","changes":"A worried parent who says this is different raises the probability of serious infection enough to examine fully and consider admission even when the traffic light is green.","lr":14.4,"target":"Serious infection","src":"Van den Bruel 2010, Lancet (parental concern LR 14.4; clinician instinct that something is wrong LR 23.5)"},{"q":"If I send you home, what will you look for, and do you know how to get back to us?","why":"Safety-netting is part of the history because serious infection evolves; the parent is the observer for the next 24 hours and needs the red flags in their words.","changes":"Clear safety-net instructions and a check of understanding allow discharge of the green child.","lr":null,"target":"Safe discharge","src":"NICE NG143 2019 (safety netting)"}],"lr":[["Parental concern that this illness is different","Serious infection",14.4],["Clinician instinct that something is wrong","Serious infection",23.5],["Petechial rash","Serious infection",6.2],["Cyanosis","Serious infection",2.7],["Poor peripheral perfusion","Serious infection",2.4],["Rapid breathing","Serious infection",1.3],["No shortness of breath and no parental concern","Pneumonia needing admission",0.16]],"lrSrc":{"Parental concern that this illness is different":"Van den Bruel 2010, Lancet (single primary care study, LR 14.4)","Clinician instinct that something is wrong":"Van den Bruel 2010, Lancet (single primary care study, LR 23.5)","Petechial rash":"Van den Bruel 2010, Lancet (LR range 6.2 to 83.7; lower bound given)","Cyanosis":"Van den Bruel 2010, Lancet (LR range 2.7 to 52.2; lower bound given)","Poor peripheral perfusion":"Van den Bruel 2010, Lancet (LR range 2.4 to 38.8; lower bound given)","Rapid breathing":"Van den Bruel 2010, Lancet (LR range 1.3 to 9.8; lower bound given)","No shortness of breath and no parental concern":"Van den Bruel 2010, Lancet (negative LR 0.14 to 0.18)"},"red":["Age under 3 months with fever 38 or over","Pale, mottled, ashen or blue","No response to social cues, does not wake or stay awake, weak high-pitched or continuous cry","Grunting, RR over 60, moderate or severe chest indrawing","Reduced skin turgor","Non-blanching rash, bulging fontanelle, neck stiffness, status epilepticus, focal signs or seizures","Fever over 5 days (Kawasaki)"],"dd":["Viral upper respiratory infection","Otitis media","Tonsillitis","Urinary tract infection","Pneumonia","Bronchiolitis","Gastroenteritis","Meningitis or meningococcal sepsis","Septic arthritis or osteomyelitis","Kawasaki disease","Roseola and viral exanthems","Malaria or imported infection","Post-immunisation fever"]},{"id":"occ","name":"The occupational history","sys":"gen","frame":"Three questions in every consultation (what do you do, do you think it is related to work, is it better away from work), then the full version for chronic or unexplained disease: a job timeline with exposures and controls, the temporal pattern, co-workers, and the fitness-to-work assessment that matches the demands of the job to what the patient can safely do.","ask":[{"q":"What exactly do you do at work, and walk me through a typical day?","why":"Job titles hide tasks: a cleaner may use chlorine and ammonia, an operator may handle isocyanates, a nurse may be exposed to latex and shift work. The exposures live in the tasks.","changes":"A task-level description reveals exposures the patient does not know are relevant and decides which specific questions follow.","lr":null,"target":"Exposure identification","src":"Newman Taylor and Cullinan, Occupational Lung Disease (Hunter's Diseases of Occupations, 10th ed)"},{"q":"Do you think your symptoms are related to work?","why":"Patients notice patterns they do not volunteer; asking directly is the quickest screen, and attribution guides what the patient will accept as a plan.","changes":"A yes opens the full occupational history; a no does not close it if the timing fits.","lr":null,"target":"Work-relatedness","src":"BOHRF occupational asthma guideline, Nicholson 2010 (recommended screening question)"},{"q":"Are the symptoms better on days off and on holiday, and worse through the working week?","why":"Removing the exposure removes the stimulus; sensitiser-induced asthma, contact dermatitis and work-related upper limb disorders all show the weekly rhythm, and symptoms may lag the shift by hours in late asthmatic reactions.","changes":"A work-related pattern means objective confirmation (serial peak flow four times a day for three weeks including days off, or patch testing) before the patient loses their job on a guess.","lr":null,"target":"Occupational asthma","src":"Malo 1991, Am Rev Respir Dis (improvement away from work sensitivity about 88%, specificity about 24%); Nicholson 2010, BOHRF"},{"q":"What do you breathe in, touch, or work near: dusts, fumes, chemicals, flour, animals, isocyanates, solvents, latex, cleaning products?","why":"Each has a disease: silica and asbestos (fibrosis, cancer), flour and isocyanates (asthma), latex and chromate (dermatitis), solvents (neuropathy, liver), animals (zoonoses and asthma). The agent is the diagnosis.","changes":"A known sensitiser or carcinogen means the specific test and, where the disease is prescribed, reporting and compensation advice.","lr":null,"target":"Specific occupational disease","src":"HSE EH40 and Hunter's Diseases of Occupations, 10th ed"},{"q":"Are you exposed to noise, vibration, heat, radiation, heavy lifting, long standing or repetitive movements?","why":"Physical hazards cause noise-induced hearing loss, hand-arm vibration syndrome, heat illness, musculoskeletal disorders; each is dose-dependent and the dose comes from the history.","changes":"A physical exposure means a targeted examination (audiometry, Tinel and cold provocation, functional assessment) and a control plan.","lr":null,"target":"Physical hazard disease","src":"HSE Control of Noise at Work and Control of Vibration at Work Regulations 2005"},{"q":"Do you do shifts or nights, how are the demands and your control over the work, and how are things with your manager and colleagues?","why":"Shift work disrupts circadian physiology (metabolic, cardiovascular, mood); the demand-control model predicts stress-related illness; bullying and conflict are the commonest cause of work-related mental ill health.","changes":"Psychosocial hazards mean a stress risk assessment and management involvement rather than only treating the symptom.","lr":null,"target":"Work-related stress and shift work disorder","src":"Karasek 1979; HSE Management Standards for work-related stress"},{"q":"Does anyone else at work have the same symptoms?","why":"A cluster among co-workers points to a common exposure and is how outbreaks of occupational asthma, dermatitis and infection are found.","changes":"Co-worker symptoms mean a workplace investigation and reporting, not just an individual diagnosis.","lr":null,"target":"Workplace cluster","src":"Hunter's Diseases of Occupations, 10th ed"},{"q":"What controls are in place: ventilation, extraction, PPE, and do you actually use them, and have you had health surveillance like spirometry, audiograms or skin checks?","why":"Exposure is the hazard minus the control; surveillance records give the baseline and the trajectory, which the examination today cannot.","changes":"Absent or unused controls mean an employer conversation; surveillance results change the interpretation of today's findings.","lr":null,"target":"Exposure control","src":"HSE COSHH Regulations 2002 (health surveillance requirements)"},{"q":"What jobs have you done before, going back to when you left school, and for how long?","why":"Asbestos-related disease appears 20 to 40 years after exposure; silicosis and noise-induced hearing loss accumulate silently; the exposure that matters may be three jobs ago.","changes":"A past exposure with a latency that fits means imaging and referral even if the current job is clean.","lr":null,"target":"Latent occupational disease","src":"BTS mesothelioma guideline 2018 (latency 20 to 50 years)"},{"q":"What are the physical and mental demands of your job: lifting how much, standing how long, driving, heights, machinery, confined spaces, shift length?","why":"Fitness to work is the match between the demands of the role and the capacity of the person; safety-critical tasks (driving, heights, machinery) have a lower tolerance for impairment because the error harms others.","changes":"Safety-critical demands raise the threshold for return and may mean temporary restriction rather than absence.","lr":null,"target":"Fitness for work","src":"Faculty of Occupational Medicine, Fitness for Work, 6th ed (Hobson & Smedley 2019)"},{"q":"What can you safely do now, and what adjustment to duties, hours or equipment would let you work?","why":"Work is generally good for health and prolonged absence predicts never returning; the fit note is designed to say 'may be fit with adjustments' and the patient usually knows what those are.","changes":"A clear capacity statement produces a fit note with specific adjustments and a review date rather than an open-ended sick note.","lr":null,"target":"Return to work plan","src":"Waddell & Burton 2006, Is work good for your health and well-being?; DWP fit note guidance"},{"q":"Have you reported this at work, and do you know whether it is a prescribed or reportable disease?","why":"Occupational asthma, dermatitis, HAVS, NIHL and asbestos diseases carry employer reporting duties (RIDDOR) and compensation routes; patients lose rights if nothing is written down.","changes":"A probable occupational disease means advising the patient to report, documenting the exposure history, and referring to occupational health.","lr":null,"target":"Reporting and compensation","src":"HSE RIDDOR 2013"},{"q":"If you have a chronic symptom: when did it start relative to starting this job or a change in the job, materials or ventilation?","why":"Temporal association with a change in process is the strongest historical evidence of causation; a new material or a broken extractor is a common trigger.","changes":"A clear onset after a workplace change means the change is investigated as the cause.","lr":null,"target":"Causation","src":"Bradford Hill 1965 (temporality); Hunter's Diseases of Occupations, 10th ed"}],"lr":[["Symptoms improve on holidays (occupational asthma)","Occupational asthma",null],["Symptoms improve on weekends (occupational asthma)","Occupational asthma",null],["Work-related change in peak flow (serial PEF, 4 readings a day, 3 weeks)","Occupational asthma",null],["Smoking over 40 pack-years","COPD",8.3],["Exposure to a known respiratory sensitiser with new-onset adult asthma","Occupational asthma",null]],"lrSrc":{"Symptoms improve on holidays (occupational asthma)":"unsourced as an LR (Malo 1991, Am Rev Respir Dis: sensitivity about 88%, specificity about 24%, implying LR+ about 1.2 and LR- about 0.5)","Symptoms improve on weekends (occupational asthma)":"unsourced as an LR (Malo 1991: weekend improvement less sensitive than holiday improvement; Vandenplas 2005, Eur Respir J)","Work-related change in peak flow (serial PEF, 4 readings a day, 3 weeks)":"unsourced as an LR (Nicholson 2010 BOHRF: serial PEF sensitivity about 64 to 82%, specificity about 77 to 100% against specific challenge)","Smoking over 40 pack-years":"Straus 2000, JAMA RCE","Exposure to a known respiratory sensitiser with new-onset adult asthma":"unsourced as an LR (BOHRF 2010: about one in six cases of new adult asthma is occupational)"},"red":["Safety-critical role (driving, heights, machinery, confined spaces) with any impairment of alertness, vision or consciousness","Suspected occupational asthma: continued exposure causes permanent loss","Asbestos or silica exposure with new respiratory symptoms","Co-worker cluster","Suicidal ideation linked to work stress or bullying","Symptoms consistent with acute poisoning (carbon monoxide, solvents, organophosphates)"],"dd":["Occupational asthma","Occupational contact dermatitis","Noise-induced hearing loss","Hand-arm vibration syndrome","Work-related upper limb disorder and back pain","Pneumoconiosis (asbestosis, silicosis)","Mesothelioma and occupational cancer","Hypersensitivity pneumonitis","Zoonoses (Q fever, brucellosis, leptospirosis)","Solvent neuropathy and encephalopathy","Work-related stress, burnout, shift work disorder","Heat illness"]},{"id":"mse","name":"Mental state and suicide risk","sys":"neuro","frame":"Screen (two Whooley questions, which rule out well), then the depressive syndrome and function, then ask about suicide in a graded way (thoughts, plan, means, intent, previous attempts, protective factors), then the known predictors (previous self-harm, hopelessness, recent discharge, alcohol, male, isolation), and accept that prediction is poor: the history is for understanding and a safety plan, not a risk score.","ask":[{"q":"During the last month, have you often been bothered by feeling down, depressed or hopeless?","why":"This and the next question are the Whooley screen; depression without low mood or anhedonia is rare, so a negative answer to both nearly excludes it, while a positive answer only earns a fuller assessment.","changes":"Two negative answers make depression unlikely; either positive means a PHQ-9 and a proper history.","lr":0.07,"target":"Major depression (both questions negative)","src":"Bosanquet 2015, BMJ Open (Whooley questions: sensitivity 95%, specificity 65%, LR+ 2.8, LR- 0.07)"},{"q":"During the last month, have you often been bothered by having little interest or pleasure in doing things?","why":"Anhedonia is the second core symptom and reflects reward circuit dysfunction; it is the one patients with masked depression still report.","changes":"A positive answer means a full assessment of the nine DSM symptoms and of function.","lr":2.8,"target":"Major depression (either question positive)","src":"Bosanquet 2015, BMJ Open"},{"q":"How are you sleeping, eating, concentrating, and is your energy different, and do you feel worthless or guilty?","why":"These are the remaining DSM symptoms; early waking, loss of appetite and weight, psychomotor change and guilt mark the biological syndrome and the severity.","changes":"Five or more symptoms over two weeks with functional impairment defines major depression and decides treatment intensity.","lr":null,"target":"Severity of depression","src":"Williams 2002, JAMA RCE; NICE NG222 depression 2022"},{"q":"Sometimes when people feel this low they have thoughts that life is not worth living, or of ending their life. Have you had thoughts like that?","why":"Asking does not plant the idea; the evidence shows no increase in suicidal ideation after being asked, and most people who die by suicide have seen a doctor in the previous month without being asked.","changes":"Any yes means the graded questions that follow, time alone, and a safety plan before the patient leaves.","lr":null,"target":"Suicidal ideation","src":"Dazzi 2014, Psychol Med (asking about suicide does not induce ideation); Luoma 2002, Am J Psychiatry (45% saw primary care in the month before death)"},{"q":"Have you thought about how you would do it, have you got the means, and have you made any preparations: a note, giving things away, putting affairs in order?","why":"The move from thought to plan to preparation is the move from ideation to intent; access to lethal means (medication stockpile, firearms, height) is modifiable and is the strongest practical lever.","changes":"A plan with available means means restricting the means today (removing medication, involving family) and same-day mental health assessment.","lr":null,"target":"Suicidal intent","src":"NICE NG225 self-harm 2022; Zalsman 2016, Lancet Psychiatry (means restriction is the best-evidenced prevention)"},{"q":"Have you ever harmed yourself or tried to end your life before, and what happened?","why":"Previous self-harm is the strongest single predictor of future suicide: about 1 in 60 die within a year of a hospital presentation, roughly 30 times the general population; the method and intent of previous attempts predict the next.","changes":"Previous self-harm means a lower threshold for specialist referral and a documented safety plan.","lr":null,"target":"Suicide risk","src":"Carroll 2014, PLoS One (1.6% suicide at 1 year after self-harm, 3.9% at 5 years); Chan 2016, Br J Psychiatry"},{"q":"Do you feel hopeless about the future, that things will never get better?","why":"Hopelessness is the cognitive state that converts depression into suicidal intent; it is a stronger predictor than the depression score itself.","changes":"Marked hopelessness raises risk and is a specific target for crisis intervention and talking therapy.","lr":null,"target":"Suicide risk","src":"Chan 2016, Br J Psychiatry (hopelessness, previous self-harm and suicidal intent as the replicated risk factors)"},{"q":"What is stopping you, and who or what is keeping you going?","why":"Reasons for living (children, faith, responsibility to others) are the protective factors; identifying them gives the content of the safety plan and the patient a reason to say them aloud.","changes":"Weak or absent protective factors raise risk; strong ones become the first line of the safety plan.","lr":null,"target":"Protective factors","src":"Stanley & Brown 2012, Cogn Behav Pract (safety planning intervention)"},{"q":"How much do you drink, and do you use any drugs?","why":"Alcohol disinhibits and is present in a large share of suicides; substance misuse roughly doubles risk and worsens every other predictor.","changes":"Alcohol misuse means addressing it in the plan and avoiding sedative prescriptions in quantity.","lr":null,"target":"Suicide risk","src":"Chan 2016, Br J Psychiatry; Hawton 2015, Lancet Psychiatry"},{"q":"Who is at home, who do you talk to, have you lost a job, a relationship or someone close recently, and have you recently left hospital or had a change in your care?","why":"Isolation, recent loss and the weeks after discharge from psychiatric care are periods of concentrated risk; the first week after discharge is the highest.","changes":"Recent discharge or loss means early follow-up within a week and involving the crisis team.","lr":null,"target":"Suicide risk","src":"Chung 2017, JAMA Psychiatry (post-discharge suicide rates highest in first week to 3 months)"},{"q":"Have you had periods of being unusually energetic, needing little sleep, spending or talking much more than usual?","why":"Bipolar depression looks like unipolar depression but antidepressants alone can induce mania; the history of elevation changes the drug.","changes":"A history of elevated mood means a mood stabiliser discussion and psychiatry input before starting an antidepressant.","lr":null,"target":"Bipolar disorder","src":"NICE CG185 bipolar disorder 2014"},{"q":"Do you hear voices or see things others do not, or feel that people are against you or that something is controlling you?","why":"Psychotic symptoms with depression mark a severe illness with higher suicide risk and a different treatment; command hallucinations are a specific danger.","changes":"Psychotic features mean urgent psychiatric assessment and usually admission.","lr":null,"target":"Psychotic depression","src":"NICE NG222 depression 2022"},{"q":"Are you able to look after yourself: eating, washing, getting to work, caring for your children?","why":"Function defines severity and is the ground for decisions about admission, time off and safeguarding of dependants.","changes":"Inability to self-care or care for dependants means admission consideration and safeguarding.","lr":null,"target":"Functional impairment","src":"NICE NG222 depression 2022"},{"q":"Do you have thoughts of harming anyone else?","why":"Homicidal ideation with depression, especially in postnatal illness and in men with family conflict, is rare but catastrophic and is only found by asking.","changes":"Thoughts of harming others mean urgent psychiatry and safeguarding of those named.","lr":null,"target":"Risk to others","src":"NICE NG225 self-harm 2022"}],"lr":[["Both Whooley questions negative","Major depression",0.07],["Either Whooley question positive","Major depression",2.8],["Previous self-harm: suicide within 1 year of hospital presentation","Suicide",null],["Classified high risk by a structured risk tool","Suicide",null],["CAGE score 2 or more","Alcohol use disorder",null],["Asking about suicide increases suicidal ideation","Iatrogenic harm",null]],"lrSrc":{"Both Whooley questions negative":"Bosanquet 2015, BMJ Open (LR- 0.07)","Either Whooley question positive":"Bosanquet 2015, BMJ Open (LR+ 2.78)","Previous self-harm: suicide within 1 year of hospital presentation":"unsourced as an LR (Carroll 2014, PLoS One: absolute risk 1.6% at 1 year, 3.9% at 5 years, about 30 times population risk)","Classified high risk by a structured risk tool":"unsourced as an LR (Large 2016, PLoS One: sensitivity 56%, specificity 79%, OR 4.8; Carter 2017, Br J Psychiatry: positive predictive value under 5%, so risk tools should not determine care)","CAGE score 2 or more":"unsourced here (Fiellin 2000, Arch Intern Med, and Kitchens 1994, JAMA RCE, report CAGE 2 or more sensitivity 43 to 94%, specificity 70 to 97%; AUDIT-C preferred)","Asking about suicide increases suicidal ideation":"unsourced as an LR (Dazzi 2014, Psychol Med: no increase; some reduction in ideation after being asked)"},"red":["Current plan with access to means","Previous attempt, especially with high lethality or regret at survival","Hopelessness with psychotic symptoms or command hallucinations","Recent discharge from psychiatric care, recent major loss","Intoxication with suicidal ideation","Unable to engage in a safety plan or no protective factors","Postnatal depression with thoughts of harming the baby"],"dd":["Major depression","Adjustment disorder","Bipolar depression","Anxiety disorder","Substance-induced mood disorder","Psychotic depression or schizophrenia","Personality disorder with recurrent self-harm","Delirium or dementia presenting with mood change","Hypothyroidism and other organic causes","Grief","Postnatal depression"]}];
const SYS={chest:"cvs",dysp:"resp",head:"neuro",abdo:"abd",back:"msk",sync:"cvs",dizz:"neuro",fever:"gen"};
HIST.pres.forEach(p=>{p.sys=p.sys||SYS[p.id]||"gen";const u=UP[p.id];if(u){if(u.ask&&u.ask.length)p.ask=u.ask;if(u.lrSrc)p.lrSrc=u.lrSrc;if(u.frame)p.frame=u.frame;}});
NEW.forEach(n=>{if(!HIST.pres.some(p=>p.id===n.id))HIST.pres.push(n);});})();
